hx_naxiang: {
    name: "纳降",
    content: "锁定技，当场上手牌数唯一最多或最少的角色发生变动时，你摸一张牌。",
    audio: "ext:华夏风云/audio/skill:3",
    trigger: { global: ["gainAfter", "loseAfter", "cardsDiscardAfter"] },
    locked: true,
    forced: true,
    direct: true,
    init(player) {
        const players = game.filterPlayer(p => p.isAlive());
        let maxCount = -1, minCount = Infinity;
        let maxPlayers = [], minPlayers = [];
        for (const p of players) {
            const cnt = p.countCards("h");
            if (cnt > maxCount) {
                maxCount = cnt;
                maxPlayers = [p];
            } else if (cnt === maxCount) {
                maxPlayers.push(p);
            }
            if (cnt < minCount) {
                minCount = cnt;
                minPlayers = [p];
            } else if (cnt === minCount) {
                minPlayers.push(p);
            }
        }
        player.storage.hx_naxiang_maxId = maxPlayers.length === 1 ? maxPlayers[0].playerid : null;
        player.storage.hx_naxiang_minId = minPlayers.length === 1 ? minPlayers[0].playerid : null;
    },
    filter(event, player) {
        if (!player.isAlive()) return false;
        const prevMax = player.storage.hx_naxiang_maxId;
        const prevMin = player.storage.hx_naxiang_minId;
        const players = game.filterPlayer(p => p.isAlive());
        let maxCount = -1, minCount = Infinity;
        let maxPlayers = [], minPlayers = [];
        for (const p of players) {
            const cnt = p.countCards("h");
            if (cnt > maxCount) {
                maxCount = cnt;
                maxPlayers = [p];
            } else if (cnt === maxCount) {
                maxPlayers.push(p);
            }
            if (cnt < minCount) {
                minCount = cnt;
                minPlayers = [p];
            } else if (cnt === minCount) {
                minPlayers.push(p);
            }
        }
        const curMaxId = maxPlayers.length === 1 ? maxPlayers[0].playerid : null;
        const curMinId = minPlayers.length === 1 ? minPlayers[0].playerid : null;
        return curMaxId !== prevMax || curMinId !== prevMin;
    },
    async content(event, trigger, player) {
        const prevMax = player.storage.hx_naxiang_maxId;
        const prevMin = player.storage.hx_naxiang_minId;
        const players = game.filterPlayer(p => p.isAlive());
        let maxCount = -1, minCount = Infinity;
        let maxPlayers = [], minPlayers = [];
        for (const p of players) {
            const cnt = p.countCards("h");
            if (cnt > maxCount) {
                maxCount = cnt;
                maxPlayers = [p];
            } else if (cnt === maxCount) {
                maxPlayers.push(p);
            }
            if (cnt < minCount) {
                minCount = cnt;
                minPlayers = [p];
            } else if (cnt === minCount) {
                minPlayers.push(p);
            }
        }
        const curMax = maxPlayers.length === 1 ? maxPlayers[0] : null;
        const curMin = minPlayers.length === 1 ? minPlayers[0] : null;
        const curMaxId = curMax ? curMax.playerid : null;
        const curMinId = curMin ? curMin.playerid : null;

        // 清除旧标记
        const allPlayers = game.filterPlayer(() => true);
        for (const p of allPlayers) {
            if (p.hasMark("hx_naxiang_max")) p.removeMark("hx_naxiang_max");
            if (p.hasMark("hx_naxiang_min")) p.removeMark("hx_naxiang_min");
        }
        // 添加新标记
        if (curMax) curMax.addMark("hx_naxiang_max");
        if (curMin) curMin.addMark("hx_naxiang_min");

        // 更新记录
        player.storage.hx_naxiang_maxId = curMaxId;
        player.storage.hx_naxiang_minId = curMinId;

        // 日志
        player.logSkill("hx_naxiang");
        let logMsg = "";
        if (curMaxId !== prevMax) {
            if (curMax) logMsg += "手牌唯一最多变为" + get.translation(curMax) + "（" + maxCount + "张）";
            else logMsg += "手牌唯一最多者消失";
        }
        if (curMinId !== prevMin) {
            if (logMsg) logMsg += "，";
            if (curMin) logMsg += "手牌唯一最少变为" + get.translation(curMin) + "（" + minCount + "张）";
            else logMsg += "手牌唯一最少者消失";
        }
        game.log(logMsg);
        await player.draw(1);
    },
    marktext: {
        hx_naxiang_max: "手牌最多",
        hx_naxiang_min: "手牌最少",
    },
    ai: { useful: 1, value: 1 },
},


