     hx_luoyingcao: {
	audio: "ext:华夏风云/audio/skill:2",
	trigger: {
		global: ["useCardAfter", "cardsDiscardAfter", "loseAfter", "equipAfter"],
	},
	filter: function (event, player) {
		if (player.countCards("he") == 0) return false;
		if (player.storage.hx_luoyingcao_used) return false;

		var cards = [];
		if (event.cards && event.cards.length) {
			cards = event.cards;
		} else if (event.card) {
			cards = [event.card];
		}
		if (!cards.length) return false;

		for (var i = 0; i < cards.length; i++) {
			if (get.suit(cards[i]) == "club") {
				var type = get.type2(cards[i]);
				if (type == "basic" || type == "trick") return true;
			}
		}
		return false;
	},
	direct: true,
	content: function () {
		"step 0"
		var cards = [];
		if (trigger.cards && trigger.cards.length) {
			cards = trigger.cards;
		} else if (trigger.card) {
			cards = [trigger.card];
		}

		var clubCards = [];
		for (var i = 0; i < cards.length; i++) {
			if (get.suit(cards[i]) == "club") {
				var type = get.type2(cards[i]);
				if (type == "basic" || type == "trick") clubCards.push(cards[i]);
			}
		}

		if (!clubCards.length) {
			event.finish();
			return;
		}

		player.storage.hx_luoyingcao_clubCards = clubCards;

		player.chooseBool("落英：是否弃置一张牌，获得" + get.cnNumber(clubCards.length) + "张梅花牌？").set("choice", true);

		"step 1"
		if (!result.bool) {
			delete player.storage.hx_luoyingcao_clubCards;
			event.finish();
			return;
		}

		"step 2"
		player.chooseCard("he", "落英：请弃置一张牌").set("ai", function (card) {
			return 10 - get.value(card);
		});

		"step 3"
		if (result.bool && result.cards && result.cards.length) {
			player.discard(result.cards);
			player.logSkill("hx_luoyingcao");
			player.gain(player.storage.hx_luoyingcao_clubCards, "gain2");
			game.log(player, "发动了【落英】，弃置了一张牌，获得了" + get.cnNumber(player.storage.hx_luoyingcao_clubCards.length) + "张梅花牌");
			player.storage.hx_luoyingcao_used = true;
		}
		delete player.storage.hx_luoyingcao_clubCards;
	},
	group: "hx_luoyingcao_clear",
	subSkill: {
		clear: {
			trigger: {
				global: "phaseAfter",
			},
			forced: true,
			popup: false,
			silent: true,
			content: function () {
				delete player.storage.hx_luoyingcao_used;
			},
		},
	},
},

