    //魂帝象

    hun_geming: {
    filterCard: true,
    filterTarget: lib.filter.notMe,
    position: "h",
    selectCard: [1, Infinity],
    enable: "phaseUse",
    complexCard: true,

    // 禁止革命自动使用【隔岸观火】，避免特殊拼点目标导致 target undefined 报错
    banCard(name) {
        return [
            "yxs_gean",
        ].includes(name);
    },

    // 判断当前是否还适合先用三民
    shouldUseSanminFirst(player) {
        if (!player.hasSkill("hun_sanmin")) return false;
        if (player.isTempBanned && player.isTempBanned("hun_sanmin")) return false;
        if (!lib.skill.hun_sanmin || !lib.skill.hun_sanmin.getCanUse) return false;

        const evt = _status.event;
        if (!evt || !evt.filterCard) return false;

        const list = ["手牌区", "牌堆顶", "牌堆底"];
        list.removeArray(player.getStorage("hun_sanmin_used"));

        // 与 hun_sanmin 原 filter 保持一致：手牌少于3张时不能选手牌区
        if (player.countCards("h") < 3) {
            list.removeArray("手牌区");
        }

        if (!list.length) return false;

        try {
            return lib.skill.hun_sanmin.getCanUse(evt, player).length > 0;
        }
        catch (e) {
            return false;
        }
    },

    check(card) {
        if (ui.selected.cards.length > 0) return 0;
        return 8 - get.value(card);
    },

    ai: {
        order(item, player) {
            // 如果三民还能用，先让 AI 用三民，再考虑革命
            if (lib.skill.hun_geming.shouldUseSanminFirst(player)) {
                return 9;
            }

            // 三民不能用后，恢复革命原来的高优先级
            return 18;
        },
        result: {
            target(player, target) {
                if (target.countCards("h") + 1 >= player.countCards("h") - 1) {
                    return 0;
                }
                const cards = player.getCards("h", c => get.effect(target, c, player, player) > 0);
                if (get.attitude(player, target) >= 0 || cards.length < 2) return 0;
                return -player.countCards("h");
            },
        },
    },

    async content(event, trigger, player) {
        const { cards, target } = event;

        await player.give(cards, target, false);

        const cards1 = player.getCards("h");
        const cards2 = target.getCards("h");

        await player.recast(cards1);
        await target.recast(cards2);

        if (cards1.length == cards2.length) {
            return;
        }

        let user,
            respond,
            cards3,
            usedNames = [],
            usedCards = [];

        if (cards1.length > cards2.length) {
            user = player;
            respond = target;
            cards3 = cards1;
        }
        else {
            user = target;
            respond = player;
            cards3 = cards2;
        }

        while (true) {
            const result = await user
                .chooseCardButton(cards3, `革命：选择对${get.translation(respond)}使用的牌`)
                .set("usedNames", usedNames)
                .set("usedCards", usedCards)
                .set("respond", respond)
                .set("filterButton", button => {
                    const { usedNames, usedCards, respond, player } = get.event();
                    const card = button.link;
                    const name = get.name(card, player);

                    if (usedCards.includes(card)) return false;
                    if (usedNames.includes(name)) return false;

                    // 禁用隔岸观火，防止特殊目标结构报错
                    if (lib.skill.hun_geming.banCard(name)) return false;

                    return player.canUse(card, respond, false);
                })
                .forResult();

            if (result.bool) {
                const card = result.links[0];

                await user.useCard(card, respond, false);

                // 保持你原来的逻辑：不启用 usedNames 限制
                // usedNames.add(get.name(result.links[0]));
                usedCards.add(card);
            }
            else {
                break;
            }
        }
    },
},

