    hun_xinghuo: {
        audio: "ext:华夏风云/audio/skill:2",
        forceunique: true,
        fixed: true,
        charlotte: true,
        superCharlotte: true,
        trigger: {
            player: "useCardToPlayer",
        },
        filter(event, player) {
            if (!event.isFirstTarget || event.targets.length != 1 || !event.target?.isIn()) return false;
            const [left, right] = get.info("hun_xinghuo").getTargets(player, event.target);
            return (left.length || right.length) && (event.card.name == "huogong" || event.card.name == "sha");
        },
        getTargets(source, target) {
            let left = [],
                right = [],
                left2 = source,
                right2 = source;
            while (!(left2 == target && right2 == target)) {
                if (left2 != target) {
                    left2 = left2.getPrevious();
                    if (left2.isIn() && left2 != target) {
                        left.push(left2);
                    }
                }
                if (right2 != target) {
                    right2 = right2.getNext();
                    if (right2.isIn() && right2 != target) {
                        right.push(right2);
                    }
                }
            }
            return [left, right];
        },
        async cost(event, trigger, player) {
            const [left, right] = get.info(event.skill).getTargets(player, trigger.target);
            if (left.length && right.length) {
                const shun = `顺时针：${left.map(i => get.translation(i)).join("、")}`,
                    ni = `逆时针：${right.map(i => get.translation(i)).join("、")}`,
                    prompt = "令顺时针或逆时针上的角色依次随机弃置一张手牌";
                const result = await player
                    .chooseButton([
                        get.prompt(event.skill),
                        prompt,
                        [
                            [
                                [left, shun],
                                [right, ni],
                            ],
                            "textbutton",
                        ],
                    ])
                    .set("ai", button => {
                        const player = get.player(),
                            trigger = get.event().getTrigger(),
                            targets = button.link;
                        let eff = 0;
                        for (let target of targets) {
                            if (lib.filter.targetEnabled2(trigger.card, player, target)) {
                                eff += get.effect(target, trigger.card, player, player);
                            }
                        }
                        return eff;
                    })
                    .forResult();
                event.result = {
                    bool: result.bool,
                    targets: result?.links?.[0],
                };
            } else {
                const targets = left.length ? left : right;
                event.result = await player.chooseBool(get.prompt2(event.skill, targets)).forResult();
                event.result.targets = targets;
            }
        },
        async content(event, trigger, player) {
            const targets = event.targets.filter(target => target.getDiscardableCards(target, "h").length);
            var list = [[], []], targetx = [];
            for (var target of targets) {
                var card = target.getDiscardableCards(target, "h").randomGet();
                await target.discard(card);
                list[0].push(target);
                list[1].push(get.color(card));
            }
            for (var i = 0; i < list[0].length; i++) {
                if (i == (list[0].length - 1)) continue;
                else if (list[1][i] == list[1][i + 1]) targetx.addArray([list[0][i], list[0][i + 1]]);
            }
            targetx = targetx.sortBySeat();
            if (targetx.length) {
                for (var i of targetx) {
                    await i.damage("fire");
                }
            }
        },
    },


