    shen_sulei: {
	enable: "phaseUse",
	usable: 1,
	audio: "ext:华夏风云/audio/skill:2",
	position: "hes",
	filter(event, player) {
		return player.countCards("hes") > 0 && game.hasPlayer((current) => player.getEnemies().includes(current));
	},
	filterCard: true,
	selectCard: 1,
	check(card) {
		if (game.hasPlayer((current) => get.is.playerNames(current, "xjzh_boss_hjguishi"))) {
			return get.color(card) === "black" ? 10 : 0;
		}
		return 8 - get.value(card);
	},
	filterTarget(card, player, target) {
		return player.getEnemies().includes(target);
	},
	selectTarget: 1,
	discard: true,
	lose: false,
	delay: false,
	async content(event, trigger, player) {
		const usedCard = event.cards[0];
		const target = event.targets[0];

		if (!usedCard || !target || !target.isIn()) {
			return;
		}

		const color = get.color(usedCard);

		while (target.isIn()) {
			const judgeResult = await target
				.judge((card) => {
					return get.color(card) === get.event().color ? -4 : 4;
				})
				.set("judge2", (result) => {
					return !result.bool;
				})
				.set("color", color)
				.forResult();

			if (judgeResult?.bool) {
				break;
			}

			await target.damage(1, player, "thunder", "nocard");

			if (!target.isIn()) {
				break;
			}

			const boolResult = await player
				.chooseBool(`〖肃雷〗：是否令${get.translation(target)}再次进行判定？`)
				.set("ai", () => {
					const player = _status.event.player;
					const target = _status.event.target;
					return get.damageEffect(target, player, player, "thunder") > 0;
				})
				.set("target", target)
				.forResult();

			if (!boolResult?.bool) {
				break;
			}
		}
	},
	ai: {
		order: 12,
		result: {
			target: -1.5,
		},
	},
},


