    hx_beige: {
        audio: "ext:华夏风云/             audio/skill:2",
        trigger: { global: "damageEnd" },
        frequent: "check",
        filter(event) {
            return event.num > 0;
        },
        check(event, player) {
            if (player.hasSkill("ll_tiandu") && player == _status.currentPhase) {
                if (!event.source || event.source == player) return false;
            }
            return get.attitude(player, event.player) > 2;
        },
        prompt2(event, player) {
            var str = `摸${event.num}张牌`;
            if (event.player !== player && event.player.isAlive()) str += `并交给${get.translation(event.player)}等量牌`;
            if (!event.source || event.source == player) str += `，然后再将至少等量牌置于牌堆顶`;
            return `${str}。`;
        },
        async content(event, trigger, player) {
            let num = trigger.num;
            await player.draw(num);
            if (trigger.player != player && trigger.player.isAlive()) {
                await player.chooseToGive(`悲歌：请选择交给${get.translation(trigger.player)}${num}张牌`, trigger.player, "he", num, true);
            }
            if (!trigger.source || trigger.source == player) {
                const result = await player
                    .chooseCard("he", [num, Infinity], `悲歌：请选择将至少${num}张牌置于牌堆顶（先选为上）`, true)
                    .set("ai", (card) => {
                        const check = get.event("check"), number = ui.selected.cards.length || 0;
                        let value = check(card, number);
                        if (number >= get.event("num")) value -= 3;
                        return value;
                    })
                    .set("num", num)
                    .set("check", (card, number) => {
                        if (!_status.currentPhase || !_status.currentPhase.isAlive()) return -1;
                        const next = _status.currentPhase.next,
                            att = get.attitude(player, next),
                            judge = next.getCards("j")[number];
                        if (judge) {
                            return get.judge(judge)(card) * att;
                        }
                        return next.getUseValue(card) * att;
                    })
                    .forResult();
                if (result.cards.length) {
                    player.lose(result.cards, ui.cardPile, "insert");
                    player.$throw(result.cards.length);
                    game.log(player, "将", get.cnNumber(result.cards.length), "张牌置于牌堆顶");
                    game.updateRoundNumber();
                }
            }
        },
        ai: {
            expose: 0.8,
            maixie: true,
            maixie_hp: true,
            effect: {
                target(card, player, target) {
                    if (get.tag(card, "damage")) {
                        if (player.hasSkillTag("jueqing", false, target)) return [1, -1];
                        if (!target.hasFriend()) return;
                        let num = 0.5;
                        if (get.attitude(player, target) > 0) {
                            if (player.needsToDiscard()) num = 0.7;
                            else num = 0.5;
                        }
                        if (target.hp >= 4) return [1, num * 2];
                        if (target.hp == 3) return [1, num * 1.5];
                        if (target.hp == 2) return [1, num * 0.5];
                    }
                },
            },
        },
    },


