    hun_mousheng: {
        audio: "ext:华夏风云/audio/skill:2",
        persevereSkill: true,
        forced: true,
        trigger: {
            player: "useCard",
            target: "useCardToTarget",
        },
        init(player, skill) {
            var types = [];
            var history = player.getHistory("useCard");
            for (var evt of history) {
                types.push(get.type2(evt.card));
            }
            for (var type of ["basic", "trick", "equip"]) {
                if (types.filter(c => c == type).length < 2) types.remove(type);
            }
            types = types.toUniqued();
            types.sort((a, b) => ["basic", "trick", "equip"].indexOf(a) - ["basic", "trick", "equip"].indexOf(b));
            if (types.length) player.addTip(skill, "谋圣 " + types.map(c => get.translation(c).slice(0, 1)).join(""), "phaseAfter");
        },
        onremove(player, skill) {
            player.removeTip(skill);
        },
        filter(event, player, name) {
            if (name == "useCard") return player.hasHistory("useCard", evt => get.type2(evt.card) == get.type2(event.card) && evt != event);
            return game.hasPlayer2(current => {
                return current.hasHistory("useCard", evt => {
                    return evt.card.name == event.card.name && evt != event.getParent() && evt.targets?.includes(player);
                });
            });
        },
        async content(event, trigger, player) {
            var name = event.triggername;
            if (name == "useCard") {
                trigger.directHit.addArray(game.players);
                game.log(trigger.card, "不可被响应");
                var types = [];
                var history = player.getHistory("useCard");
                for (var evt of history) {
                    types.push(get.type2(evt.card));
                }
                for (var type of ["basic", "trick", "equip"]) {
                    if (types.filter(c => c == type).length < 2) types.remove(type);
                }
                types = types.toUniqued();
                types.sort((a, b) => ["basic", "trick", "equip"].indexOf(a) - ["basic", "trick", "equip"].indexOf(b));
                if (types.length) player.addTip(event.name, "谋圣 " + types.map(c => get.translation(c).slice(0, 1)).join(""), "phaseAfter");
            } else {
                trigger.getParent().excluded.add(player);
            }
        },
        ai: {
            effect: {
                target(card, player, target) {
                    if (
                        game.hasPlayer2(current => {
                            return current.hasHistory("useCard", evt => evt.card.name == card.name && evt.targets?.includes(target));
                        })
                    ) {
                        return "zeroplayertarget";
                    }
                },
            },
        },
    },


