    //魂郭荣

    hun_yingfa: {
    audio: "ext:华夏风云/audio/skill:2",
    trigger: {
        player: "phaseDiscardBefore",
    },
    filter(event, player) {
        // 本回合至少有一名角色使用过牌（包括自己）
        return game.hasPlayer(function(p) {
            return p.getHistory("useCard").length > 0;
        });
    },
    forced: true,
    async content(event, trigger, player) {
        // 1. 找出本回合使用过牌的所有角色（包括自己）
        var targets = game.filterPlayer(function(p) {
            return p.getHistory("useCard").length > 0;
        });
        var lostCards = [];

        // 2. 令每个角色将手牌数调整至3
        for (var i = 0; i < targets.length; i++) {
            var t = targets[i];
            if (!t.isIn()) continue;
            var hc = t.countCards("h");
            if (hc > 3) {
                var res = await t.chooseToDiscard(hc - 3, "h", "英伐：" + get.translation(t) + "弃置" + (hc - 3) + "张手牌").set("ai", function(card) {
                    return 10 - get.value(card);
                }).forResult();
                if (res.bool && res.cards) {
                    for (var j = 0; j < res.cards.length; j++) {
                        var card = res.cards[j];
                        if (get.type(card) !== "equip") {
                            lostCards.push(card);
                        }
                    }
                }
            } else if (hc < 3) {
                await t.draw(3 - hc);
            }
        }

        if (lostCards.length === 0) return;

        // 3. 选择一名其他角色（使用牌的目标排除自己）
        var tc = await player.chooseTarget(get.prompt2("hun_yingfa"), 1, function(card, p, target) {
            if (target === p) return false;
            for (var i = 0; i < lostCards.length; i++) {
                if (p.canUse(lostCards[i], target, false)) return true;
            }
            return false;
        }).set("ai", function(target) {
            var eff = 0;
            for (var i = 0; i < lostCards.length; i++) {
                if (player.canUse(lostCards[i], target, false)) {
                    eff += get.effect(target, lostCards[i], player, player);
                }
            }
            return eff;
        }).forResult();

        if (!tc.bool || !tc.targets || !tc.targets.length) return;

        var tar = tc.targets[0];
        var usable = lostCards.filter(function(c) {
            return player.canUse(c, tar, false);
        });
        if (usable.length === 0) return;

        // 4. 询问是否使用
        var bool = await player.chooseBool("是否对" + get.translation(tar) + "使用" + get.translation(usable) + "？").set("ai", function() {
            return true;
        }).forResult();

        if (bool.bool) {
            for (var i = 0; i < usable.length; i++) {
                if (tar.isAlive()) {
                    await player.useCard(usable[i], tar);
                }
            }
        }
    },
    ai: {
        expose: 0.3,
    },
},

    hun_tuzhi: {
    audio: "ext:华夏风云/audio/skill:2",
    trigger: {
        global: ["changeSkillsEnd", "loseAfter"]
    },
    forced: true,
    filter: function (event, player) {
        // 锁定技，回合外触发
        var current = _status.currentPhase;
        if (current === player) return false;  // 自己回合内不触发
        if (event.player == player) return false;  // 自己弃置/失去技能不触发

        if (event.name == "changeSkills") {
            return event.removeSkill && event.removeSkill.filter(skill => {
                let info = get.info(skill);
                if (!info || get.is.empty(info) || info.unique || info.charlotte) return false;
                return true;
            }).length > 0;
        } else if (event.name == "lose") {
            return event.type === "discard";
        }
    },
    content: async function (event, trigger, player) {
        if (trigger.name == "changeSkills") {
            let skills = trigger.removeSkill.filter(skill => {
                let info = get.info(skill);
                if (!info || get.is.empty(info) || info.unique || info.charlotte) return false;
                return true;
            });

            await player.addSkills(skills);
            return;
        } else if (trigger.name == "lose") {
            let cards = trigger.cards2.slice(0);
            let evt = trigger.getl(player);
            if (evt && evt.cards) cards.removeArray(evt.cards);
            await player.gain(cards.filter(function (card) {
                return get.position(card, true) == "d";
            }), "gain2");
            if (trigger.cards.filterInD().length) await player.gain(trigger.cards.filterInD(), "gain2");
        }
    },
},


