    hx_renshu: {
    audio: "ext:华夏风云/audio/skill:2",
    enable: "phaseUse",
    usable: 1,
    filterTarget(card, player, target) {
        return target.countGainableCards(player, "he");
    },
    async content(event, trigger, player) {
        const target = event.targets[0];
        const {
            bool, links
        } = await player.gainPlayerCard(target, "he", [1, 3], true).forResult();
        if (bool) {
            player.addTempSkill("hx_renshu_effect");
            player.markAuto("hx_renshu_effect", [target]);
            player
                .when("phaseUseAfter")
                .then(() => {
                    if (player.hasHistory("sourceDamage")) return;
                    const cards = player.getCards("he", function (card) {
                        return links.includes(card);
                    });
                    if (target && target.isIn() && cards.length) {
                        player.give(cards, target);
                    }
                })
                .vars({ target: target, links: links });
        }
    },
    ai: {
        order: 7,
        result: {
            target(player, target) {
                if (!target.countGainableCards(player, "he")) return 0;

                const att = get.attitude(player, target);

                // 优先对敌人发动
                if (att < 0) {
                    let value = 0;
                    const cards = target.getCards("he", card => {
                        return lib.filter.canBeGained(card, target, player);
                    });

                    cards.forEach(card => {
                        value += Math.max(1, get.value(card, target));
                    });

                    value = Math.min(value, 18);

                    return -Math.max(1, value / 4);
                }

                // 不主动对友方发动
                if (att > 0) {
                    return 0;
                }

                return -0.5;
            },
        },
    },
    subSkill: {
        effect: {
            charlotte: true,
            onremove: true,
            mod: {
                playerEnabled(card, player, target) {
                    if (player.getStorage("hx_renshu_effect").includes(target)) return false;
                },
            },
        },
    },
},

