    //扁鹊

    hx_bamai: {
    audio: "ext:华夏风云/audio/skill:2",
    enable: "phaseUse",
    usable: 1,
    filterTarget(card, player, target) {
        return target != player && target.countCards("h") > 0;
    },
    async content(event, trigger, player) {
        const target = event.target;
        const hs = target.getCards("h");

        if (!hs.length) return;

        const result = await player.chooseCardButton(hs, [0, 2])
            .set("ai", function (button) {
                const player = get.player();
                const target = _status.event.targetx;
                const card = button.link;
                const value = get.value(card, target);
                const color = get.color(card);

                // 优先选低价值黑色牌（全黑能触发用桃）
                if (color == "black") {
                    return 12 - value;
                }

                // 红色牌只有价值很低时才考虑
                return 6 - value;
            })
            .set("targetx", target)
            .forResult();

        if (!result.bool || !result.links?.length) {
            return;
        }

        const links = result.links;

        // 弃置选中的牌
        await target.discard(links);

        // 目标摸等量的牌
        await target.draw(links.length);

        // 检查是否全是黑色
        const allBlack = links.every(card => get.color(card) == "black");

        // 全是黑色且目标有体力损失时，对其使用桃
        if (allBlack && target.isDamaged()) {
            await player.useCard({ name: "tao" }, target);
        }
    },
    ai: {
        order: 8,
        threaten: 1.5,
        expose: 0.2,
        result: {
            target(player, target) {
                const att = get.attitude(player, target);

                // 不对敌人发动
                if (att <= 0) return 0;

                // 评估友方手牌中有多少低价值黑色牌
                const blackLowValue = target.getCards("h", card => {
                    return get.color(card) == "black" && get.value(card, target) < 5;
                }).length;

                const redLowValue = target.getCards("h", card => {
                    return get.color(card) == "red" && get.value(card, target) < 4;
                }).length;

                // 有2张以上低价值黑色牌，收益最高
                if (blackLowValue >= 2) return 3 + (target.isDamaged() ? 2 : 0);

                // 有1张低价值黑色牌，也不错
                if (blackLowValue >= 1) return 2 + (target.isDamaged() ? 1 : 0);

                // 只有红色废牌，收益一般
                if (redLowValue >= 1) return 1;

                return 0.5;
            },
        },
    },
},

