    //义妁

    hx_zhenjiu: {
    audio: "ext:华夏风云/audio/skill:2",
    nobracket: true,
    trigger: {
        global: "damageEnd",
    },
    usable: 1,
    filter(event, player) {
        return event.player?.isIn() && event.player.countCards("h") > 0;
    },
    logTarget: "player",
    check(event, player) {
        if (get.attitude(player, event.player) < 0) {
            return event.player.isHealthy();
        }
        return get.recoverEffect(event.player, player, player) > 0;
    },
    async content(event, trigger, player) {
        const target = trigger.player;
        const handCards = target.getCards("h");

        // 统计手牌中有哪些花色
        var suits = {};
        for (var i = 0; i < handCards.length; i++) {
            suits[get.suit(handCards[i])] = true;
        }
        var suitList = Object.keys(suits);
        if (suitList.length === 0) return;

        // 让玩家选择一种花色
        var suitRes = await player.chooseControl(suitList)
            .set("prompt", "选择一种花色，将" + get.translation(target) + "该花色的所有手牌置于其武将牌上")
            .set("ai", function() {
                // 选择牌数最多的花色，最大化移除效果
                var bestSuit = suitList[0];
                var bestCount = 0;
                for (var i = 0; i < suitList.length; i++) {
                    var count = 0;
                    for (var j = 0; j < handCards.length; j++) {
                        if (get.suit(handCards[j]) === suitList[i]) count++;
                    }
                    if (count > bestCount) {
                        bestCount = count;
                        bestSuit = suitList[i];
                    }
                }
                return bestSuit;
            })
            .forResult();

        var chosenSuit = suitRes.control;
        var suitCards = [];
        for (var i = 0; i < handCards.length; i++) {
            if (get.suit(handCards[i]) === chosenSuit) {
                suitCards.push(handCards[i]);
            }
        }

        // 将该花色所有牌置于目标武将牌上
        if (suitCards.length > 0) {
            target.addSkill("hx_zhenjiu_effect");
            const exp = target.addToExpansion(suitCards, "giveAuto", target);
            exp.gaintag.add("hx_zhenjiu_effect");
            await exp;
            game.log(player, "将", get.translation(target), "的" + get.translation(chosenSuit) + "花色手牌置于其武将牌上");
        }

        // 令其回复一点体力
        await target.recover();
    },
    subSkill: {
        effect: {
            trigger: {
                player: "phaseBegin",
            },
            forced: true,
            charlotte: true,
            async content(event, trigger, player) {
                const cards = player.getExpansions("hx_zhenjiu_effect");
                if (cards.length) {
                    await player.gain(cards, "draw");
                    game.log(player, "收回了武将牌上的牌");
                }
                player.removeSkill("hx_zhenjiu_effect");
            },
            onremove(player, skill) {
                const cards = player.getExpansions(skill);
                if (cards.length) {
                    player.loseToDiscardpile(cards);
                }
            },
            intro: {
                mark(dialog, storage, player) {
                    var cards = player.getExpansions("hx_zhenjiu_effect");
                    if (player.isUnderControl(true)) {
                        dialog.addAuto(cards);
                    } else {
                        return "共有" + get.cnNumber(cards.length) + "张牌";
                    }
                },
                markcount: "expansion",
            },
        },
    },
},

    hx_miaoshou: {
    name: "妙手",
    trigger: { global: "dying" },
    usable: 1,
    filter(event, player) {
        return event.player && event.player.isIn();
    },
    logTarget: "player",
    check(event, player) {
        // 敌方角色濒死时不发动
        if (get.attitude(player, event.player) < 0) return false;
        // 友方角色濒死时发动
        return true;
    },
    async content(event, trigger, player) {
        var target = trigger.player;
        var hasPeach = player.countCards("h", { name: "tao" }) > 0;

        if (!hasPeach) {
            // 选项1：从牌堆中找一张桃
            var peachCard = null;
            for (var i = 0; i < ui.cardPile.childNodes.length; i++) {
                if (ui.cardPile.childNodes[i].name === "tao") {
                    peachCard = ui.cardPile.childNodes[i];
                    break;
                }
            }
            if (peachCard) {
                await player.gain(peachCard, "gain2");
                game.log(player, "从牌堆中获得了一张【桃】");
            } else {
                for (var j = 0; j < ui.discardPile.childNodes.length; j++) {
                    if (ui.discardPile.childNodes[j].name === "tao") {
                        await player.gain(ui.discardPile.childNodes[j], "gain2");
                        game.log(player, "从弃牌堆中获得了一张【桃】");
                        break;
                    }
                }
            }
        } else {
            // 选项2：弃一张桃，令濒死角色回复体力至1
            var discardRes = await player.chooseCard("h", 1, function(card) {
                return card.name === "tao";
            }).set("prompt", "选择一张【桃】弃置，令" + get.translation(target) + "回复体力至1").set("ai", function(card) {
                return 8 - get.value(card);
            }).forResult();

            if (discardRes.bool && discardRes.cards.length > 0) {
                player.discard(discardRes.cards);
                var recoverNum = 1 - target.hp;
                if (recoverNum > 0) {
                    await target.recover(recoverNum);
                }
                game.log(player, "弃置了一张【桃】，令", target, "回复体力至1");
            }
        }
    },
    ai: {
        save: true,
        result: { player: 1, target: 1 },
    },
},


