    hx_huisheng: {
        enable: ["chooseToUse"],
        filter: function (event, player) {
            if (!game.hasPlayer(t => t.hp > 0 && t.hp < t.maxHp - 1)) return false;
            if (!player.isUnderControl()) {
                return game.hasPlayer(t => t.hp > 0 && t.hp < t.maxHp - 1 && get.attitude(player, t) > 0);
            }
            return true;
        },
        async content(event, trigger, player) {
            let target = null;
            const candidates = game.filterPlayer(t => t.hp > 0 && t.hp < t.maxHp - 1);
            if (candidates.length === 0) return;

            const result = await player.chooseTarget(
                "请选择一名角色，将其体力回复至体力上限-1",
                (card, player, target) => candidates.includes(target)
            ).set("ai", (target) => {
                let att = get.attitude(player, target);
                if (att <= 0) return 0;
                return (target.maxHp - 1 - target.hp) * 2;
            }).forResult();

            if (result && result.targets && result.targets.length) {
                target = result.targets[0];
            }

            if (!player.isUnderControl() && target && get.attitude(player, target) <= 0) {
                const friend = candidates.find(t => get.attitude(player, t) > 0);
                if (friend) target = friend;
                else return;
            }

            if (!target) return;
            const newHp = target.maxHp - 1;
            if (target.hp < newHp) {
                await target.recoverTo(newHp);
                game.log(player, "对", target, "发动了【养生】，回复至", newHp, "点体力");
            }
        },
        ai: {
            order: 8,
            result: {
                player: (player) => {
                    return game.hasPlayer(t => t.hp > 0 && t.hp < t.maxHp - 1 && get.attitude(player, t) > 0) ? 8 : 0;
                }
            }
        },
        group: ["hx_huisheng_dying"],
        subSkill: {
            dying: {
                trigger: { global: "dying" },
                filter: (event, player) => event.player.hp < 0 && get.attitude(player, event.player) > 0,
                async content(event, trigger, player) {
                    const target = trigger.player;
                    if (!target || target.hp >= 0) return;
                    const result = await player.chooseBool()
                        .set("prompt", "是否发动【养生】救回" + get.translation(target) + "？")
                        .set("prompt2", "将其体力回复至0点")
                        .set("ai", () => true)
                        .forResult();
                    if (result && result.bool) {
                        await target.changeHp(-target.hp);
                        game.log(player, "发动了【养生】，将", target, "的体力从", target.hp, "回复至0");
                    }
                }
            }
        },
    },


