    hun_shashen: {
    audio: "ext:华夏风云/audio/skill:2",
    trigger: {
        player: "gainAfter",
    },
    filter(event, player) {
        if (!event.cards) return false;
        var hasSha = event.cards.some(card => get.name(card) == "sha" && player.getCards("h").includes(card));
        if (!hasSha) return false;
        if (player.storage.hun_shashen_processing) {
            if (!player.storage.hun_shashen_queue) player.storage.hun_shashen_queue = [];
            event.cards.forEach(card => {
                if (get.name(card) == "sha" && player.getCards("h").includes(card) && !player.storage.hun_shashen_queue.includes(card)) {
                    player.storage.hun_shashen_queue.push(card);
                }
            });
            return false;
        }
        return true;
    },
    check(event, player) {
        return game.hasPlayer(function (target) {
            return player.canUse({ name: "sha" }, target);
        });
    },
    init: function (player) {
        player.storage.hun_shashen = {};
    },
    group: ["hun_shashen_track"],
    forceunique: true,
    fixed: true,
    charlotte: true,
    superCharlotte: true,
    content: function () {
        "step 0"
        player.storage.hun_shashen_processing = true;
        event.shas = trigger.cards.filter(function (card) {
            return get.name(card) == "sha" && player.getCards("h").includes(card);
        });
        if (!event.shas.length) {
            player.storage.hun_shashen_processing = false;
            event.finish();
            return;
        }
        event.num = 0;
        "step 1"
        if (event.num < event.shas.length) {
            var card = event.shas[event.num];
            event.currentCard = card;
            player.chooseTarget("杀神：是否使用进入手牌区的【杀】？", function (card, player, target) {
                return player.canUse(_status.event.currentCard, target);
            }).set("currentCard", card).set("ai", function (target) {
                return get.effect(target, { name: "sha" }, _status.event.player, _status.event.player);
            });
        } else {
            event.goto(4);
        }
        "step 2"
        if (result.targets && result.targets.length) {
            player.storage.hun_shashen_tracking = 0;
            player.useCard(event.currentCard, result.targets[0]);
        } else {
            event.num++;
            if (event.num < event.shas.length) {
                event.goto(1);
            } else {
                event.goto(4);
            }
            return;
        }
        "step 3"
        var dealtDamage = (player.storage.hun_shashen_tracking || 0) > 0;
        delete player.storage.hun_shashen_tracking;
        if (dealtDamage) {
            var check = function (list) {
                for (var i = 0; i < list.length; i++) {
                    var info = lib.skill[list[i]];
                    if (!info) continue;
                    if (info.shaRelated) return true;
                    if (info.shaRelated === false) return false;
                    if (get.skillInfoTranslation(list[i], player).includes("【杀】")) return true;
                }
                return false;
            };
            var list = get.gainableSkills(function (info, skill) {
                if (player.storage.hun_shashen[skill]) return false;
                if (player.hasSkill(skill)) return false;
                var skillList = [skill];
                game.expandSkills(skillList);
                return check(skillList);
            }, player);
            var count = 0;
            for (var i in player.storage.hun_shashen) {
                count++;
            }
            if (count < 999999 && list.length) {
                var skill = list.randomGet();
                player.addAdditionalSkill("hun_shashen", skill, true);
                player.storage.hun_shashen[skill] = 999999;
                player.popup(skill);
                game.log(player, "获得了技能", "【" + get.translation(skill) + "】");
                player.markSkill("hun_shashen");
            }
        }
        event.num++;
        if (event.num < event.shas.length) {
            event.goto(1);
        }
        "step 4"
        if (player.storage.hun_shashen_queue && player.storage.hun_shashen_queue.length) {
            var queued = player.storage.hun_shashen_queue.filter(function (card) {
                return player.getCards("h").includes(card);
            });
            player.storage.hun_shashen_queue = [];
            if (queued.length) {
                event.shas = queued;
                event.num = 0;
                event.goto(1);
                return;
            }
        }
        player.storage.hun_shashen_processing = false;
    },
    mark: true,
    intro: {
        content(storage, player) {
            var count = 0;
            var str = "已获得技能：";
            for (var i in storage) {
                count++;
                str += get.translation(i) + "、";
            }
            if (count === 0) return "无";
            return str.slice(0, -1);
        },
    },
    "skill_id": "hun_shashen",
    "_priority": 0,
},

