hx_yanjitang: {
	audio: "ext:华夏风云/audio/skill:3",

	init: function (player, skill) {
		player.storage.hx_yanjitang_first = true;
		player.storage.hx_yanjitang_last = 0;
		player.storage.hx_yanjitang_inUse = false;
	},

	mod: {
		// 第一张基本牌/普通锦囊牌无距离限制
		targetInRange: function (card, player, target, now) {
			if (!player.storage.hx_yanjitang_inUse) return;
			if (player.storage.hx_yanjitang_first === false) return;
			var type = get.type(card);
			var type2 = get.type2 ? get.type2(card) : type;
			if (type == "basic" || (type == "trick" && type2 != "delay")) {
				return true;
			}
		},
		// 直接修改选目标数量上限
		selectTarget: function (card, player, range) {
			if (!player.storage.hx_yanjitang_inUse) return;
			var type = get.type(card);
			var type2 = get.type2 ? get.type2(card) : type;
			if (type != "basic" && !(type == "trick" && type2 != "delay")) return;

			// 只对需要选目标的牌生效（如杀、顺手牵羊等）
			// 跳过桃等无需选目标的牌
			if (range[1] <= 0) return;

			if (player.storage.hx_yanjitang_first !== false) {
				// 第一张牌：可指定任意名目标
				range[1] = Infinity;
			} else {
				// 后续牌：目标数至多为上一张牌目标数的一半（向上取整，至少为1）
				var last = player.storage.hx_yanjitang_last || 0;
				if (last <= 0) return;
				var max = Math.ceil(last / 2);
				if (max < 1) max = 1;
				// 只减少不增加：不把原本只能选1名的牌扩大到多名
				if (range[1] === Infinity || range[1] < 0 || range[1] > max) {
					range[1] = max;
				}
			}
		},
	},

	group: [
		"hx_yanjitang_record",
		"hx_yanjitang_reset",
		"hx_yanjitang_clear",
	],
	subSkill: {
		// 记录目标数，标记第一张已用
		record: {
			charlotte: true,
			forced: true,
			popup: false,
			silent: true,
			trigger: {
				player: "useCard",
			},
			filter: function (event, player) {
				if (!player.storage.hx_yanjitang_inUse) return false;
				var type = get.type(event.card);
				var type2 = get.type2 ? get.type2(event.card) : type;
				return type == "basic" || (type == "trick" && type2 != "delay");
			},
			content: function () {
				player.storage.hx_yanjitang_first = false;
				player.storage.hx_yanjitang_last = trigger.targets ? trigger.targets.length : 0;
			},
		},

		// 出牌阶段开始：重置标记
		reset: {
			charlotte: true,
			forced: true,
			popup: false,
			silent: true,
			trigger: {
				player: "phaseUseBegin",
			},
			content: function () {
				player.storage.hx_yanjitang_first = true;
				player.storage.hx_yanjitang_last = 0;
				player.storage.hx_yanjitang_inUse = true;
			},
		},

		// 出牌阶段结束：清除标记
		clear: {
			charlotte: true,
			forced: true,
			popup: false,
			silent: true,
			trigger: {
				player: "phaseUseEnd",
			},
			content: function () {
				player.storage.hx_yanjitang_inUse = false;
			},
		},
	},
},


