      //高阳公主
      
    hx_jiaojin: {
    audio: "ext:华夏风云/audio/skill:2",
    trigger: { player: 'useCard' },
    forced: true,
    locked: true,
    group: 'hx_jiaojin_clear',
    filter(event, player) {
        if (_status.currentPhase !== player) return false;

        // 泣戈转化出的【杀】不计入骄矜
        if (player.storage.hx_qige_using) return false;

        return typeof get.number(event.card) == 'number';
    },
    content() {
        'step 0'
        const num = get.number(trigger.card);
        const last = player.storage.hx_jiaojin_last;

        // 第一张牌只记录点数，不触发摸牌或失去体力
        if (typeof last == 'number') {
            if (num > last) {
                player.draw();
            }
            else {
                player.loseHp();
            }
        }

        player.storage.hx_jiaojin_last = num;
    },
    mod: {
        aiOrder(player, card, num) {
            if (_status.currentPhase !== player) return num;

            const point = get.number(card);
            if (typeof point != 'number') return num;

            const last = player.storage.hx_jiaojin_last;
            const name = get.name(card, player);
            const type = get.type(card, null, player);
            const value = get.value(card, player);
            const useful = get.useful(card, player);

            // 是否能通过掉血触发泣戈获得收益
            const hasQige = player.hasSkill('hx_qige') && player.countCards('he') > 0;
            const canUseQige = hasQige && player.hp > 1;

            // 第一张牌：仍然倾向先出小点数，但不压低关键牌
            if (typeof last != 'number') {
                let bonus = Math.max(0, 8 - point) / 10;

                // 桃、关键锦囊、装备不应该为了“铺垫点数”被过度延后
                if (name == 'tao' && player.isDamaged()) bonus += 3;
                if (type == 'trick') bonus += Math.min(2, value / 4);
                if (type == 'equip') bonus += Math.min(1.5, value / 5);

                return num + bonus;
            }

            // 点数递增：正常强烈鼓励，因为能摸牌
            if (point > last) {
                let bonus = 5 + point / 20;

                // 好牌递增更应该出
                if (value >= 6) bonus += 1.5;
                if (type == 'trick') bonus += 1;
                if (name == 'tao' && player.isDamaged()) bonus += 3;

                return num + bonus;
            }

            // 点数不递增：会失去体力，但不能一刀切禁止
            let penalty = 4 + Math.max(0, last - point) / 4;

            // 有泣戈且血量安全时，掉血有收益，降低惩罚
            if (canUseQige) {
                penalty -= 2.5;

                // 血量较高时，可以更积极卖血触发泣戈
                if (player.hp >= 3) penalty -= 1.5;

                // 手牌越多，泣戈重铸和转杀空间越大
                if (player.countCards('he') >= 3) penalty -= 1;
            }

            // 桃在需要回血时优先级很高，不要因为会掉血就完全不用
            if (name == 'tao' && player.isDamaged()) {
                if (player.hp <= 1) return num + 8;
                if (canUseQige) return num + 3;
                return num + 1;
            }

            // 关键锦囊牌不要被骄矜压死
            if (type == 'trick') {
                if (value >= 7) return num + 2;
                if (canUseQige && value >= 5) return num + 1;
                penalty -= Math.min(2, value / 4);
            }

            // 高价值牌可以接受掉血使用
            if (value >= 7 || useful >= 7) {
                if (canUseQige) return num + 1.5;
                return num - 0.5;
            }

            // 体力危险时，仍然保守
            if (player.hp <= 1) penalty += 5;

            return num - penalty;
        },
    },
    ai: {
        threaten: 1.5,
        effect: {
            player(card, player) {
                if (_status.currentPhase !== player) return;

                const point = get.number(card);
                if (typeof point != 'number') return;

                const last = player.storage.hx_jiaojin_last;
                if (typeof last != 'number') return;

                const name = get.name(card, player);
                const type = get.type(card, null, player);
                const value = get.value(card, player);

                const hasQige = player.hasSkill('hx_qige') && player.countCards('he') > 0;
                const canUseQige = hasQige && player.hp > 1;

                // 点数递增：摸牌收益
                if (point > last) {
                    return [1, 1.2];
                }

                // 桃在残血时仍然该用
                if (name == 'tao' && player.isDamaged()) {
                    if (player.hp <= 1) return [1, 4];
                    if (canUseQige) return [1, 1.5];
                    return [1, 0.5];
                }

                // 高价值锦囊可以接受卖血
                if (type == 'trick' && value >= 6) {
                    if (canUseQige && player.hp >= 2) return [1, 0.8];
                    if (player.hp <= 1) return [0, -3];
                    return [1, -0.5];
                }

                // 有泣戈且血量安全时，失去体力不一定是坏事
                if (canUseQige) {
                    if (player.hp >= 3) return [1, 0.6];
                    return [1, -0.2];
                }

                // 没有泣戈或体力危险时，正常认为掉血是负面
                if (player.hp <= 1) return [0, -4];
                return [1, -1.2];
            },
        },
    },
    subSkill: {
        clear: {
            trigger: { global: ['phaseBegin', 'phaseAfter'] },
            forced: true,
            silent: true,
            popup: false,
            filter(event, player) {
                return player.storage.hx_jiaojin_last != null;
            },
            content() {
                delete player.storage.hx_jiaojin_last;
            },
        },
    },
},

