    hx_zhizhengxu: {
        audio: "ext:华夏风云/audio/newlol_lienata:3",
        enable: "phaseUse",
        usable: 1,
        filterTarget: true,
        content: function () {
            "step 0"
            var targetCardsCount = target.countCards("h");
            // 用于记录发生变动的角色及其变动数值
            event.changedPlayers = [];

            // 1. 遍历所有人执行平衡逻辑
            var list = game.filterPlayer();
            for (var i = 0; i < list.length; i++) {
                var currentPlayer = list[i];
                player.line(currentPlayer);
                var currentHandCount = currentPlayer.countCards("h");
                var diff = targetCardsCount - currentHandCount;

                if (diff > 0) {
                    // 摸牌
                    currentPlayer.draw(diff);
                    event.changedPlayers.push([currentPlayer, diff]); // 记录正值
                } else if (diff < 0) {
                    // 弃牌
                    currentPlayer.chooseToDiscard("h", -diff, true);
                    event.changedPlayers.push([currentPlayer, diff]); // 记录负值
                }
            }

            "step 1"
            // 过滤掉已经死亡或不合法的目标，只保留在此过程中变动过的角色
            var choices = event.changedPlayers.filter(pair => pair[0].isIn());
            if (choices.length > 0) {
                player.chooseTarget("是否令一名变动过的角色反向执行一半的效果？", function (card, player, target) {
                    // 仅限刚才变动过的角色
                    return _status.event.changedTargets.includes(target);
                }).set("changedTargets", choices.map(p => p[0])).set("ai", function (target) {
                    // AI 简易逻辑：让对手弃牌，或者让队友摸牌
                    var pair = _status.event.choices.find(p => p[0] === target);
                    var diff = pair[1];
                    if (get.attitude(_status.event.player, target) > 0) {
                        return diff < 0 ? 1 : 0; // 如果队友刚才弃了牌，补偿他
                    } else {
                        return diff > 0 ? 1 : 0; // 如果对手刚才摸了牌，削弱他
                    }
                }).set("choices", choices);
            } else {
                event.finish();
            }

            "step 2"
            if (result.bool) {
                var selected = result.targets[0];
                var pair = event.changedPlayers.find(p => p[0] === selected);
                var originalDiff = pair[1]; // 拿到最初的变动值

                // 计算反向数值：一半并向上取整
                var half = Math.ceil(Math.abs(originalDiff) / 2);

                player.line(selected);
                if (originalDiff > 0) {
                    // 原本是摸牌(>0)，现在反向执行：弃牌
                    selected.chooseToDiscard("h", half, true);
                } else {
                    // 原本是弃牌(<0)，现在反向执行：摸牌
                    selected.draw(half);
                }
            }
        },
        ai: {
            order: 2,
            result: {
                target: function (player, target) {
                    // 1. 模拟如果以 target 为基准，全场手牌变动带来的收益总和
                    var targetCount = target.countCards("h");
                    var totalValue = 0;
                    var list = game.filterPlayer();

                    for (var i = 0; i < list.length; i++) {
                        var current = list[i];
                        var currentCount = current.countCards("h");
                        var diff = targetCount - currentCount;
                        var att = get.attitude(player, current); // 获取玩家对该角色的态度 (正为友，负为敌)

                        // 基础收益计算：diff > 0 摸牌，diff < 0 弃牌
                        // 对队友(att > 0)：摸牌收益为正，弃牌收益为负
                        // 对敌人(att < 0)：摸牌收益为负，弃牌收益为正
                        var effect = diff * att;

                        // 权重修正：手牌从 1 变 0 的弃牌价值极高，手牌从高变更高收益递减
                        if (currentCount <= 2 && diff < 0) effect *= 1.5; // 拆掉敌人救命手牌权重增加

                        totalValue += effect;
                    }

                    // 2. 考虑 step 1 的二次反转收益
                    // AI 会预判：我还能选一个人“反向补偿/削弱”。这通常会给收益最高的那个人
                    // 这里简单加一个权重偏移：找到那个变动最大的人，假设我们能反转他
                    var maxDiff = 0;
                    for (var i = 0; i < list.length; i++) {
                        maxDiff = Math.max(maxDiff, Math.abs(targetCount - list[i].countCards("h")));
                    }
                    totalValue += (maxDiff / 2) * 5; // 假设能反向操作带来额外收益

                    // 3. 只有当总价值为正且显著时才发动
                    if (totalValue <= 0) return 0;

                    // 返回一个分值，分值越高 AI 越优先选这个 target
                    if (get.attitude(player, target) > 0) return totalValue / 5;
                    else return -totalValue / 5;
                }
            }
        }
    },
