          hx_yanchi: {
    audio: "yeyan",
    enable: "phaseUse",
    filter(event, player) {
        // X为你手牌缺少的花色数（用countCards+回调，兼容filterEnable阶段）
        const allSuits = ["heart", "diamond", "club", "spade"];
        let missingCount = 0;
        for (const suit of allSuits) {
            if (player.countCards("h", card => get.suit(card) === suit) === 0) {
                missingCount++;
            }
        }
        const x = missingCount;

        // 已使用次数 < X 才可发动
        if (player.countMark("hx_yanchi_used") >= x) return false;

        if (player.countCards("h") == 0) {
            return false;
        }
        var players = game.filterPlayer();
        for (var i = 0; i < players.length; i++) {
            if (players[i] != player && players[i].countCards("h") > 0) return true;
        }
        return false;
    },
    content() {
        "step 0"
        player.addMark("hx_yanchi_used", 1);
        player.chooseTarget(get.prompt2("hx_yanchi"), true, function(card, player, target) {
            return target != player && target.countCards("h");
        }).set("ai", function(target) {
            var att = get.attitude(_status.event.player, target);
            if (att > 0) return -1;
            if (att == 0) return 0.1;
            return get.damageEffect(target, player, player, "fire");
        });
        "step 1"
        if (result.bool) {
            player.line(result.targets[0], "red");
            event.target = result.targets[0];
            player.chooseCard("h", true).ai = function(card) {
                return 20 - get.value(card);
            };
        }
        "step 2"
        if (result.bool) {
            event.cardp = result.cards[0];
            event.target.chooseCard("h", true).ai = function(card) {
                return 20 - get.value(card);
            };
        }
        "step 3"
        if (result.bool) {
            event.cardt = result.cards[0];
            player.showCards(event.cardp);
            event.target.showCards(event.cardt);
        }
        "step 4"
        player.$giveAuto(event.cardp, event.target);
        event.target.gain(event.cardp, player);
        event.target.give(event.cardt, player);
        "step 5"
        var suitp = get.suit(event.cardp);
        var suitt = get.suit(event.cardt);
        if (suitp != suitt) {
            event.target.damage("fire", player);
        }
    },
    group: "hx_yanchi_clear",
    ai: {
        order: 1,
        expose: 0.6,
        threaten: 2,
        result: {
            player(player, target) {
                var cards = player.getCards("he");
                var flag = 0;
                for (var i = 0; i < cards.length; i++) {
                    var card = cards[i];
                    if (7 - get.value(card) > 0 && card.name != "tao") flag = 1;
                }
                if (flag == 0) return -1;
                return 1;
            },
        },
    },
},

