    //魔安禄山

    mo_jiaoxia: {
        audio: "ext:华夏风云/audio/skill:2",
        enable: "phaseUse",
        filter: function (event, player) {
            return player.hp > 0 || player.maxHp > 1;
        },
        content: function () {
            "step 0"
            var choices = [];
            if (player.hp > 0) choices.push("失去一点体力");
            if (player.maxHp > 1) choices.push("减少一点体力上限");

            // AI 智能选择代价
            player.chooseControl(choices)
                .set("prompt", "狡黠：选择一项")
                .set("ai", function () {
                    var player = _status.event.player;
                    // 若体力为1，优先减上限避免濒死
                    if (player.hp === 1) return "减少一点体力上限";
                    // 若体力上限已很低（≤2），优先失去体力
                    if (player.maxHp <= 2) return "失去一点体力";
                    // 若手牌中有桃或能回血的牌，可以承受失去体力
                    var hasTao = player.countCards("h", "tao") > 0;
                    // 若自己血量健康且不是卖血将，优先失去体力；否则减上限
                    var isMaiXie = player.hasSkillTag("maixie");
                    if (player.hp >= 3 && !isMaiXie) return "失去一点体力";
                    if (isMaiXie && player.hp > 2) return "失去一点体力";
                    // 默认选择减上限
                    return "减少一点体力上限";
                });

            "step 1"
            event.choice = result.control;
            if (event.choice == "失去一点体力") {
                player.loseHp(1);
            } else {
                player.loseMaxHp(1);
            }

            "step 2"
            var list = [];
            for (var i of lib.inpile) {
                var info = lib.card[i];
                if (!info) continue;
                if ((info.type === "basic" || info.type === "trick") && !info.notarget) {
                    list.push([info.type, "", i]);
                }
            }
            if (!list.length) {
                event.finish();
                return;
            }

            // AI 智能选择视为使用的牌
            player.chooseButton(["狡黠：视为使用一张基本牌或锦囊牌", [list, "vcard"]])
                .set("ai", function (button) {
                    var player = _status.event.player;
                    var cardName = button.link[2];
                    var card = { name: cardName };
                    // 优先选择能造成伤害的锦囊
                    if (cardName === "juedou") return 9;
                    if (cardName === "nanman") return 8.5;
                    if (cardName === "wanjian") return 8.2;
                    if (cardName === "sha") return 7;
                    // 辅助类锦囊
                    if (cardName === "wuzhong") return 6.5;
                    if (cardName === "taoyuan") return 6;
                    if (cardName === "wugu") return 5;
                    // 控制类
                    if (cardName === "guohe") return 7.5;
                    if (cardName === "shunshou") return 7.3;
                    if (cardName === "jiedao") return 6.8;
                    // 基本牌
                    if (cardName === "tao") return 7.2;
                    if (cardName === "jiu") return 5;
                    if (cardName === "shan") return 4;
                    // 默认使用 getUseValue
                    return player.getUseValue(card);
                });

            "step 3"
            if (result && result.bool) {
                player.chooseUseTarget({ name: result.links[0][2] }, true);
            }
        },
        ai: {
            order: function (skill, player) {
                // 如果体力或体力上限富裕，尽早使用
                if (player.maxHp > 4 && player.hp > 2) return 9;
                // 濒死时不用
                if (player.hp <= 1 && player.maxHp <= 2) return 0;
                // 默认中等优先级
                return 6;
            },
            result: {
                player: function (player) {
                    // 评估整体收益
                    var hasGoodTarget = false;
                    // 检查是否有可造成伤害的锦囊目标
                    var cards = ["juedou", "nanman", "wanjian", "sha"];
                    for (var i of cards) {
                        if (game.hasPlayer(function (target) {
                            return player.canUse({ name: i }, target) && get.effect(target, { name: i }, player, player) > 0;
                        })) {
                            hasGoodTarget = true;
                            break;
                        }
                    }
                    if (hasGoodTarget) return 1.5;
                    // 如果手牌中有桃且自己残血，使用桃也不错
                    if (player.hp <= 2 && player.countCards("h", "tao") === 0) return 1;
                    return 0.8;
                }
            }
        }
    },

