        hx_tuqiongbixian: {
    audio: "ext:华夏风云/audio/skill:2",
    trigger: {
        player: ["showCards", "loseAfter"],
    },
    filter: function (event, player) {
        var cards = [];
        if (event.name == 'showCards') {
            cards = event.cards || [];
            var parent = event.getParent();
            if (parent && parent.name == 'useCard') return false;
        } else if (event.name == 'lose') {
            cards = event.hs || [];
        }
        var hasSha = false;
        for (var i = 0; i < cards.length; i++) {
            if (get.name(cards[i]) == 'sha') { hasSha = true; break; }
        }
        if (!hasSha) return false;
        if (event.name == 'lose') {
            var parent = event.getParent();
            if (parent && parent.name == 'useCard' && !parent.respondTo) return false;
        }
        return true;
    },
    check: function (event, player) {
        return game.hasPlayer(function (current) {
            return current != player && current.isAlive() && get.attitude(player, current) < 0;
        });
    },
    content: function () {
        "step 0"
        var seers = [];
        if (trigger.name == 'showCards') {
            for (var i = 0; i < game.players.length; i++) {
                if (game.players[i] != player && game.players[i].isAlive()) seers.push(game.players[i]);
            }
        } else if (trigger.name == 'lose') {
            var parent = trigger.getParent();
            if (parent && parent.name == 'gain') {
                if (parent.player && parent.player != player && parent.player.isAlive()) {
                    seers.push(parent.player);
                }
            } else {
                for (var i = 0; i < game.players.length; i++) {
                    if (game.players[i] != player && game.players[i].isAlive()) seers.push(game.players[i]);
                }
            }
        }
        var targets = seers.filter(function (p) {
            return get.damageEffect(p, player, player) > 0;
        });
        if (targets.length == 0) {
            event.finish();
            return;
        }
        player.chooseTarget("图穷匕见：请选择一名见到此【杀】的角色，对其造成1点伤害", function (card, player, target) {
            return seers.includes(target);
        }).set("ai", function (target) {
            return get.damageEffect(target, player, player);
        }).set("targetprompt", "伤害");
        "step 1"
        if (result.bool) {
            player.line(result.targets);
            result.targets[0].damage(1, player);
        }
    }
},


