    hx_zuijiu: {
        mod: {
            cardUsable: function (card, player, num) {
                if (card.name == "jiu") return Infinity;
            },
        },
        audio: "ext:华夏风云/audio/skill:2",
        enable: "chooseToUse",
        filterCard: function (card) {
            return get.suit(card) == "spade";
        },
        viewAs: {
            name: "jiu",
        },
        onuse: function (result, player) {
            player.draw();

        },
        position: "hs",
        viewAsFilter: function (player) {
            if (!player.countCards("hs", { suit: "spade" })) return false;
            return true;
        },
        prompt: "将一张黑桃手牌当酒使用",
        check: function (cardx, player) {
            if (player && player == cardx.player) return true;
            if (_status.event.type == "dying") return 1;
            var player = _status.event.player;
            var shas = player.getCards("hs", function (card) {
                return card != cardx && get.name(card, player) == "sha";
            });
            if (!shas.length) return -1;
            if (shas.length > 1 && (player.getCardUsable("sha") > 1 || player.countCards("hs", "zhuge"))) {
                return 0;
            }
            shas.sort(function (a, b) {
                return get.order(b) - get.order(a);
            });
            var card = false;
            if (shas.length) {
                for (var i = 0; i < shas.length; i++) {
                    if (shas[i] != cardx && lib.filter.filterCard(shas[i], player)) {
                        card = shas[i]; break;
                    }
                }
            }
            if (card) {
                if (game.hasPlayer(function (current) {
                    return (get.attitude(player, current) < 0 &&
                        !current.hasShan()
                        && current.hp + current.countCards("h", { name: ["tao", "jiu"] }) > 1 + (player.storage.jiu || 0)
                        && player.canUse(card, current, true, true) &&
                        !current.hasSkillTag("filterDamage", null, {
                            player: player,
                            card: card,
                            jiu: true,
                        }) &&
                        get.effect(current, card, player) > 0);
                })) {
                    return 4 - get.value(cardx);
                }
            }
            return -1;
        },
        ai: {
            threaten: 1.5,
            basic: {
                useful: function (card, i) {
                    if (_status.event.player.hp > 1) {
                        if (i == 0) return 4;
                        return 1;
                    }
                    if (i == 0) return 7.3;
                    return 3;
                },
                value: function (card, player, i) {
                    if (player.hp > 1) {
                        if (i == 0) return 5;
                        return 1;
                    }
                    if (i == 0) return 7.3;
                    return 3;
                },
            },
            order: function () {
                return get.order({ name: "sha" }) + 0.2;
            },
            result: {
                target: function (player, target) {
                    if (target && target.isDying()) return 2;
                    if (target && !target.isPhaseUsing()) return 0;
                    if (lib.config.mode == "stone" && !player.isMin()) {
                        if (player.getActCount() + 1 >= player.actcount) return 0;
                    }
                    var shas = player.getCards("h", "sha");
                    if (shas.length > 1 && (player.getCardUsable("sha") > 1 || player.countCards("h", "zhuge"))) {
                        return 0;
                    }
                    shas.sort(function (a, b) {
                        return get.order(b) - get.order(a);
                    })
                    var card;
                    if (shas.length) {
                        for (var i = 0; i < shas.length; i++) {
                            if (lib.filter.filterCard(shas[i], target)) {
                                card = shas[i]; break;
                            }
                        }
                    }
                    else if (player.hasSha() && player.needsToDiscard()) {
                        if (player.countCards("h", "hufu") != 1) {
                            card = { name: "sha" };
                        }
                    }
                    if (card) {
                        if (game.hasPlayer(function (current) {
                            return (get.attitude(target, current) < 0 &&
                                target.canUse(card, current, null, true) &&
                                !current.hasSkillTag("filterDamage", null, {
                                    player: player,
                                    card: card,
                                    jiu: true,
                                }) &&
                                get.effect(current, card, target) > 0);
                        })) {
                            return 1;
                        }
                    }
                    return 0;
                },
            },
            tag: {
                save: 1,
                recover: 0.1,
            },
        },
    },


