hx_zhengge: {
    nobracket: true,
    audio: "ext:华夏风云/audio/skill:2",
    trigger: { global: "phaseAfter" },
    filter(event, player) {
        return get.info("hx_zhengge").countEmptyAreas(player) > 0 &&
            ui.discardPile && ui.discardPile.childNodes &&
            ui.discardPile.childNodes.length > 0;
    },
    countEmptyAreas(player) {
        let n = 0;
        if (player.countCards("h") == 0) n++;
        if (player.countCards("e") == 0) n++;
        if (player.countCards("j") == 0) n++;
        return n;
    },
    async content(event, trigger, player) {
        const emptyAreas = get.info("hx_zhengge").countEmptyAreas(player);
        if (!emptyAreas || !ui.discardPile.childNodes.length) return;

        // 先从弃牌堆顶一次性取出，避免装备满槽时反复取同一张导致死循环
        const cards = [];
        for (let i = 0; i < emptyAreas; i++) {
            if (!ui.discardPile.childNodes.length) break;
            const card = ui.discardPile.lastChild;
            if (!card) break;
            card.remove();
            cards.push(card);
        }

        let gained = 0;
        for (const card of cards) {
            if (get.type(card) == "equip") {
                const subtype = get.subtype(card);
                // 槽位启用 且 该装备子类型槽位为空 才能装备；否则视为满装
                const slotEmpty =
                    player.hasEnabledSlot(subtype) &&
                    player.countCards("e", c => get.subtype(c) == subtype) == 0;
                if (slotEmpty) {
                    await player.equip(card);
                    gained++;
                } else {
                    player.storage.hx_zhengge_extra = (player.storage.hx_zhengge_extra || 0) + 1;
                    player.markSkill("hx_zhengge");
                    game.log(player, "装备已满，获得一次额外", "#g【锋袭】", "发动机会");
                    card.goto(ui.discardPile);
                }
            } else {
                await player.gain(card, "gain2");
                gained++;
            }
        }
        if (gained) {
            game.log(player, "从弃牌堆获得了", gained, "张牌");
        }
    },
    intro: {
        content(storage, player) {
            const extra = player.storage.hx_zhengge_extra || 0;
            return extra > 0 ? "拥有" + extra + "次额外【锋袭】发动机会" : null;
        },
    },
    group: ["hx_zhengge_reset"],
    subSkill: {
        reset: {
            trigger: { global: "roundEnd" },
            silent: true,
            charlotte: true,
            content() {
                delete player.storage.hx_zhengge_extra;
                player.unmarkSkill("hx_zhengge");
            },
        },
    },
    ai: {
        threaten: 1.4,
    },
},


