    //周幽王
    
    hx_fengluan: {
	audio: "ext:华夏风云/audio/skill:2",
	enable: "phaseUse",
	// 无 usable：不限次数，由 filter 自身限制
	filter(event, player) {
		var minOther = Infinity;
		var hasOther = false;
		for (var p of game.players) {
			if (!p.isIn()) continue;
			if (p == player) continue;
			hasOther = true;
			var n = p.countCards("h");
			if (n < minOther) minOther = n;
		}
		if (!hasOther) return false;
		if (minOther <= 0) return false; // 无法成为"唯一最少"
		var target = minOther - 1;
		return player.countCards("h") != target;
	},
	check(event, player) {
		// 受伤时倾向发动（可回血）；手牌较多时也可发动制造南蛮伤害
		if (player.isDamaged()) return true;
		return player.countCards("h") >= 3;
	},
	async content(event, trigger, player) {
		// 计算"全场唯一最少"目标值 = 其他存活角色最少手牌数 - 1
		var minOther = Infinity;
		for (var p of game.players) {
			if (!p.isIn()) continue;
			if (p == player) continue;
			var n = p.countCards("h");
			if (n < minOther) minOther = n;
		}
		var target = Math.max(0, minOther - 1);
		var current = player.countCards("h");
		// 双向调整至 target
		if (current > target) {
			await player.chooseToDiscard("h", current - target, true);
		} else if (current < target) {
			await player.draw(target - current);
		}
		// 回复1点体力（满血时自动无效）
		await player.recover();
		// 视为使用一张【南蛮入侵】，目标为所有其他存活角色
		var targets = game.filterPlayer(function (p) {
			return p != player && p.isIn();
		});
		if (targets.length) {
			await player.useCard({ name: "nanman", isCard: true }, targets);
		}
	},
	ai: {
		order: 6,
		result: {
			player: 1,
		},
		threaten: 1.3,
	},
},

