    hun_wendingzhongyuan: {
    mark: true,
    marktext: "鼎",
    intro: {
        content: function(storage, player) {
            var red = player.storage.hun_wendingzhongyuan_red || 0;
            var black = player.storage.hun_wendingzhongyuan_black || 0;
            return "本轮获得红色牌：" + red + " 张<br>本轮被使用黑色牌：" + black + " 张";
        }
    },
    init: function(player) {
        if (!player.hasSkill('hun_wendingzhongyuan_counter')) {
            player.addSkill('hun_wendingzhongyuan_counter');
        }
        if (!player.hasSkill('hun_wendingzhongyuan_damage')) {
            player.addSkill('hun_wendingzhongyuan_damage');
        }
    },
    onremove: function(player) {
        player.removeSkill('hun_wendingzhongyuan_counter');
        player.removeSkill('hun_wendingzhongyuan_damage');
        player.removeSkill('hun_wendingzhongyuan_restrict');
        delete player.storage.hun_wendingzhongyuan_red;
        delete player.storage.hun_wendingzhongyuan_black;
    },
    trigger: { global: "roundStart" },
    getX: function(player) {
        // 基础1次 + 一鸣惊人加成，与诸葛连弩等装备无关
        var yiming = player.storage.hun_yimingjingren_sha || 0;
        return 1 + yiming;
    },
    async cost(event, trigger, player) {
        player.storage.hun_wendingzhongyuan_red = 0;
        player.storage.hun_wendingzhongyuan_black = 0;
        player.updateMarks();

        var x = lib.skill.hun_wendingzhongyuan.getX(player);
        const { bool } = await player.chooseBool("是否发动【问鼎中原】获得" + x + "张红色牌？（X为你的出杀次数）").set("ai", () => true).forResult();
        event.result = { bool: bool };
    },
    async content(event, trigger, player) {
        var x = lib.skill.hun_wendingzhongyuan.getX(player);

        var cards = [];
        var pile = ui.cardPile.childNodes;
        for (var i = pile.length - 1; i >= 0 && cards.length < x; i--) {
            if (get.color(pile[i]) == 'red') {
                cards.push(pile[i]);
            }
        }

        for (var i = 0; i < cards.length; i++) {
            cards[i].remove();
            cards[i].fix();
        }

        if (cards.length > 0) {
            await player.gain(cards, "gain2");
        }

        player.storage.hun_wendingzhongyuan_red = cards.length;
        player.updateMarks();
    },
},

