    //勾践

    hx_wxcd: {
    audio: "ext:华夏风云/audio/skill:3",
    trigger: {
        player: "phaseZhunbeiBegin",
    },
    filter(event, player) {
        return true;
    },
    async content(event, trigger, player) {
        const result = await player.chooseBool(
            "卧薪尝胆：是否跳过你本回合的出牌阶段和弃牌阶段并摸一张牌？"
        )
            .set("ai", () => {
                const player = _status.event.player;

                // 手里有诸葛连弩，不跳过
                if (player.countCards("h", card => get.name(card) == "zhuge") > 0) {
                    return false;
                }

                // 手牌达到15张且场上有诸葛连弩，不跳过
                if (
                    player.countCards("h") >= 15 &&
                    game.hasPlayer(current => {
                        return current.getEquips("zhuge").length > 0;
                    })
                ) {
                    return false;
                }

                // 伤害牌足够多（7 张及以上），不跳过
                const damageCards = player.countCards("h", card => {
                    const name = get.name(card);
                    return name == "sha" || name == "juedou" || name == "huogong" ||
                        name == "lebu" || name == "shunshou" || name == "guohe" ||
                        name == "wuzhong" || name == "taoyuan";
                });
                if (damageCards >= 7) {
                    return false;
                }

                // 残血（体力值<=2）且有可用牌时，不跳过
                if (player.hp <= 2) {
                    if (player.countCards("h", card => {
                        return player.hasUseTarget(card);
                    }) > 0) {
                        return false;
                    }
                }

                // 其他情况一律跳过
                return true;
            })
            .forResult();

        if (!result.bool) return;

        player.addTempSkill("hx_wxcd_skip_use", {
            player: "phaseAfter",
        });
        player.addTempSkill("hx_wxcd_skip_discard", {
            player: "phaseAfter",
        });

        await player.draw();

        // 移动牌逻辑：有友方时才移动，避免把自己的牌移给敌人
        if (player.canMoveCard()) {
            const friendlies = game.filterPlayer(current => {
                return current != player && get.attitude(player, current) > 0;
            });

            const enemies = game.filterPlayer(current => {
                return current != player && get.attitude(player, current) < 0;
            });

            // 没有友方但场上有敌人时，不移动
            if (!friendlies.length && enemies.length > 0) {
                return;
            }

            const move = await player.chooseBool("卧薪尝胆：是否移动场上的一张牌？")
                .set("ai", () => true)
                .forResult();

            if (move.bool) {
                await player.moveCard(true);
            }
        }
    },
    subSkill: {
        skip_use: {
            charlotte: true,
            trigger: {
                player: "phaseUseBefore",
            },
            forced: true,
            popup: false,
            content() {
                trigger.cancel();
            },
        },
        skip_discard: {
            charlotte: true,
            trigger: {
                player: "phaseDiscardBefore",
            },
            forced: true,
            popup: false,
            content() {
                trigger.cancel();
            },
        },
    },
    ai: {
        expose: 0.2,
    },
},

