        //黄巢
        
hx_junping: {
    name: "均平",
    content: "游戏开始时，你可令场上体力上限唯一最少的角色获得体力上限最多的角色的1点体力上限，然后重复此流程直至你的体力上限不为全场唯一最少。",
    audio: "ext:华夏风云/audio/skill:3",
    trigger: { global: "gameStart" },
    filter: function(event, player) {
        var players = game.filterPlayer(function(current) { return current.isAlive(); });
        var minHp = Math.min.apply(Math, players.map(p => p.maxHp));
        if (player.maxHp !== minHp) return false;
        var minCount = players.filter(p => p.maxHp === minHp).length;
        return minCount === 1;
    },
    prompt: function(event, player) {
        return "是否发动【均平】？";
    },
    content: function() {
        "step 0"
        var players = game.filterPlayer(function(current) { return current.isAlive(); });
        var maxHp = Math.max.apply(Math, players.map(p => p.maxHp));
        var minHp = Math.min.apply(Math, players.map(p => p.maxHp));
        // 无法继续转移则结束
        if (maxHp <= minHp) {
            game.log('【均平】发动结束！');
            return;
        }
        var maxPlayers = players.filter(p => p.maxHp === maxHp);
        var minPlayers = players.filter(p => p.maxHp === minHp);
        event.minPlayer = minPlayers[0];
        event._chosenMaxPlayers = maxPlayers; // 存储本次循环的候选数组

        // 清除上一次的 control，避免残留
        delete event.control;

        if (maxPlayers.length > 1) {
            player.chooseControl(maxPlayers.map(p => get.translation(p.name)))
                .set('prompt', '请选择一名角色失去1点体力上限')
                .set('ai', function() { return 0; });
        } else {
            event.maxPlayer = maxPlayers[0];
        }
        "step 1"
        // 获取本次循环选中的角色
        var maxPlayer;
        if (event._chosenMaxPlayers.length > 1) {
            // 确保 control 有效，默认为 0
            var control = (event.control !== undefined) ? event.control : 0;
            maxPlayer = event._chosenMaxPlayers[control];
        } else {
            maxPlayer = event._chosenMaxPlayers[0];
        }
        if (!maxPlayer) maxPlayer = event._chosenMaxPlayers[0];

        var minPlayer = event.minPlayer;
        maxPlayer.loseMaxHp(1);
        minPlayer.gainMaxHp(1);
        game.log(minPlayer, '从', maxPlayer, '处获得了1点体力上限');

        // 检查是否继续
        var newPlayers = game.filterPlayer(function(current) { return current.isAlive(); });
        var newMinHp = Math.min.apply(Math, newPlayers.map(p => p.maxHp));
        var newMaxHp = Math.max.apply(Math, newPlayers.map(p => p.maxHp));
        var newMinCount = newPlayers.filter(p => p.maxHp === newMinHp).length;
        if (player.maxHp === newMinHp && newMinCount === 1 && newMinHp < newMaxHp) {
            event.goto(0);
        } else {
            game.log('【均平】发动结束！');
        }
    },
    ai: { useful: 1, value: 1 }
},


