         hx_fcdx: {
    audio: "ext:华夏风云/audio/skill:3",
    enable: "phaseUse",
    usable: 1,
    filter(event, player) {
        return player.countCards("h", card => get.type(card) == "basic") > 0;
    },
    content: function () {
        "step 0"
        player.chooseTarget("焚巢捣穴：选择一名其他角色，将所有基本牌交给该角色", function (card, player, target) {
            return target != player;
        }).set("ai", function (target) {
            var player = _status.event.player;
            var att = get.attitude(player, target);
            if (att > 0) return 0;  // 友方不选

            // 计算伤害潜力
            var giveCount = player.countCards("h", card => get.type(card) == "basic");
            var gainCount = target.countCards("he", card => get.type(card) != "basic");
            var damage = giveCount - gainCount;

            if (damage > 0) {
                // 能造成火焰伤害，优先选择伤害高的目标
                return damage * 10 + get.damageEffect(target, player, player, "fire");
            }
            // 无法造成伤害，但可以夺取对方非基本牌
            return gainCount * 2;
        });
        "step 1"
        if (result.bool) {
            event.target = result.targets[0];
            event.giveCards = player.getCards("h", card => get.type(card) == "basic");
            player.logSkill("hx_fcdx", event.target);
            if (event.giveCards.length > 0) {
                player.give(event.giveCards, event.target);
            }
        } else {
            event.finish();
        }
        "step 2"
        event.gainCards = event.target.getCards("he", card => get.type(card) != "basic");
        if (event.gainCards.length > 0) {
            player.gain(event.gainCards, event.target, "giveAuto", "bySelf");
        }
        "step 3"
        var num = event.giveCards.length - event.gainCards.length;
        if (num > 0) {
            event.target.damage(num, "fire");
        }
    },
    ai: {
        order: 7,
        result: {
            player(player) {
                return 1;
            },
            target(player, target) {
                if (!target) return 0;  // 引擎评估技能时可能不传目标，需保护
                var giveCount = player.countCards("h", card => get.type(card) == "basic");
                var gainCount = target.countCards("he", card => get.type(card) != "basic");
                var damage = giveCount - gainCount;
                if (damage > 0) {
                    return -damage;
                }
                return 0;
            },
        },
    },
},



