hx_miji: {
    nobracket: true,
    audio: "ext:华夏风云/audio/skill:2",
    direct: true,
    trigger: {
        global: "useCardToPlayered",
    },
    filter(event, player) {
        if (!event || event.name != "useCardToPlayered") return false;
        if (player.storage._hx_miji_acting) return false;
        const card = event.card;
        if (!card) return false;
        if (!get.tag(card, 'damage')) return false;
        const target = event.target;
        if (!target || !target.isIn()) return false;
        // 防止同一张牌对同一目标重复发动（群体牌可对不同目标分别发动）
        if (card.hx_miji_targets && card.hx_miji_targets.includes(target)) return false;
        return true;
    },
    check(event, player) {
        const target = event.target;

        // 自己是目标：不依赖attitude（对自己通常返回0），直接按血量判断
        if (target == player) {
            let score = 0;
            if (player.hp >= 3) score += 6;      // 血量充足，摸两张牌赚
            else if (player.hp == 2) score += 3;  // 勉强可以
            else score -= 8;                       // 残血无法闪避，危险
            return score > 0;
        }

        const att = get.attitude(player, target);
        let score = 0;

        // 友方目标：给牌但无法闪避
        if (att > 0) {
            if (target.hp >= 3) score += 8;
            else if (target.hp == 2) score += 4;
            else score -= 4; // 残血友方不发动，可能致死
        }

        // 敌方目标：令其无法闪避，但要给两张牌
        if (att < 0) {
            const cardName = event.card ? event.card.name : "";
            if (cardName == "sha" && target.countCards("h", "shan")) score += 6;
            else if (cardName == "juedou" && target.countCards("h", "sha")) score += 6;
            else score -= 2; // 敌方本就无法响应，无收益
            score -= 3; // 给敌方两张牌的代价
        }

        return score > 0;
    },
    async content(event, trigger, player) {
        const target = trigger.target;
        const card = trigger.card;

        player.storage._hx_miji_acting = true;

        // 是否发动
        const useResult = await player
            .chooseBool(
                get.prompt("hx_miji"),
                "是否发动【秘计】：令 " + get.translation(target) +
                " 摸两张牌，且" + get.translation(card) + "不可被响应？"
            )
            .set("ai", () => {
                // 自己是目标：按血量判断
                if (target == player) {
                    return player.hp >= 2;
                }
                const att = get.attitude(player, target);
                // 友方且能扛住伤害
                if (att > 0 && target.hp >= 2) return true;
                // 敌方且有响应牌，封锁其闪避
                if (att < 0) {
                    if (card.name == "sha" && target.countCards("h", "shan")) return true;
                    if (card.name == "juedou" && target.countCards("h", "sha")) return true;
                }
                return false;
            })
            .forResult();

        if (!useResult.bool) {
            delete player.storage._hx_miji_acting;
            return;
        }

        player.logSkill("hx_miji");

        // 目标摸两张牌
        await target.draw(2);

        // 标记此牌已对该目标发动过秘计
        if (!card.hx_miji_targets) card.hx_miji_targets = [];
        card.hx_miji_targets.push(target);

        // 令此牌不可响应：将目标加入 directHit 列表
        if (trigger.directHit && trigger.directHit.add) {
            trigger.directHit.add(target);
        } else if (trigger.getParent) {
            let p = trigger.getParent();
            while (p) {
                if (p.directHit && p.directHit.add) {
                    p.directHit.add(target);
                    break;
                }
                p = p.getParent ? p.getParent() : null;
            }
        }

        game.log(player, "发动", "#g【秘计】", "，令", target, "摸了两张牌，且", card, "不可被响应");

        delete player.storage._hx_miji_acting;
    },
    ai: {
        threaten: 1.2,
    },
    skill_id: "hx_miji",
    _priority: 0,
},


