hx_yifajiang: {
    audio: "ext:华夏风云/audio/skill:3",
    enable: "phaseUse",
    usable: 2,
    group: ["hx_yifajiang_draw", "hx_yifajiang_clear"],
    filterTarget: function (card, player, target) {
        return target != player && player.canCompare(target);
    },
    content: function () {
        "step 0"
        event.name = "hx_yifajiang";

        if (!player.storage.hx_yifajiang_count) player.storage.hx_yifajiang_count = 0;
        event.source = player;
        event.target = target;

        "step 1"
        if (!event.source.isAlive() || !event.target.isAlive()) {
            event.finish();
            return;
        }
        if (!event.source.canCompare(event.target)) {
            event.finish();
            return;
        }

        event.source.chooseToCompare(event.target).set("ai", function (card) {
            var player = _status.event.player;
            var num = get.number(card);

            // 从当前事件往父事件找【弈伐】事件
            var evt = _status.event;
            var count = 0;
            var owner = null;

            while (evt) {
                if (evt.name == "hx_yifajiang") {
                    owner = evt.player;
                    break;
                }
                evt = evt.parent;
            }

            if (owner && owner.storage) {
                count = owner.storage.hx_yifajiang_count || 0;
            }

            // 第一次、第二次拼点：优先用小点数牌
            if (count < 2) {
                return 20 - num;
            }

            // 第三次及以后：收益变高，优先用大点数牌争最后胜者
            return num;
        });

        "step 2"
        player.storage.hx_yifajiang_count++;
        player.markSkill("hx_yifajiang");

        var winner = null;
        var loser = null;

        if (result.winner && result.loser) {
            winner = result.winner;
            loser = result.loser;
        }
        else if (result.bool) {
            winner = event.source;
            loser = event.target;
        }
        else if (result.tie) {
            game.log("此次", "#g【弈伐】", "拼点没有胜者");
            event.finish();
            return;
        }
        else {
            winner = event.target;
            loser = event.source;
        }

        if (!winner || !loser || !winner.isAlive() || !loser.isAlive()) {
            event.finish();
            return;
        }

        player.storage.hx_yifajiang_winner = winner;
        game.log(winner, "成为本回合", "#g【弈伐】", "最后一次拼点的胜者");

        event.winner = winner;
        event.loser = loser;

        var count = player.storage.hx_yifajiang_count;
        var list = ["翻面"];

        if (loser.countCards("he") > 0) {
            list.push("弃置" + count + "张牌");
        }

        if (winner.isAlive() && loser.isAlive() && loser.canCompare(winner)) {
            list.push("再拼点");
        }

        loser.chooseControl(list).set("prompt", "弈伐：请选择一项").set("ai", function () {
            var player = _status.event.player;
            var winner = _status.event.winner;
            var count = _status.event.count;

            var max = 0;
            var hs = player.getCards("h");
            for (var i = 0; i < hs.length; i++) {
                max = Math.max(max, get.number(hs[i]));
            }

            // 已经翻面时，选择翻面相当于翻回来
            if (player.isTurnedOver()) {
                return "翻面";
            }

            // 拼点次数较高且自己有大牌，优先再拼点争夺最后胜者
            if (player.canCompare(winner) && count >= 2 && max >= 11) {
                return "再拼点";
            }

            // 前期弃牌代价较低，优先弃牌保状态
            if (player.countCards("he") >= count && count <= 2) {
                return "弃置" + count + "张牌";
            }

            // 有很大的牌时，也可以尝试再拼点
            if (player.canCompare(winner) && max >= 12) {
                return "再拼点";
            }

            return "翻面";
        }).set("count", count).set("winner", winner);

        "step 3"
        var choice = result.control;
        var count = player.storage.hx_yifajiang_count;

        if (choice == "翻面") {
            event.loser.turnOver();
            event.finish();
        }
        else if (choice && choice.indexOf("弃置") == 0) {
            var num = Math.min(count, event.loser.countCards("he"));
            if (num > 0) {
                event.loser.chooseToDiscard("he", num, true);
            }
            event.finish();
        }
        else if (choice == "再拼点") {
            event.source = event.loser;
            event.target = event.winner;
            event.goto(1);
        }
    },
    intro: {
        content: function (storage, player) {
            var str = "";
            if (player.storage.hx_yifajiang_count) {
                str += "本回合已因【弈伐】拼点" + player.storage.hx_yifajiang_count + "次";
            }
            if (player.storage.hx_yifajiang_winner) {
                str += "；最后一次赢的一方为" + get.translation(player.storage.hx_yifajiang_winner);
            }
            return str || "本回合尚未因【弈伐】拼点";
        },
    },
    ai: {
        order: 8,
        result: {
            target: function (player, target) {
                if (!player.canCompare(target)) return 0;
                if (player.countCards("h") > target.countCards("h")) return -1;
                if (player.countCards("h") >= 2) return -0.5;
                return 0;
            },
        },
    },
},

