        //孙策
        
        "hx_zhizheng": {
    audio: "ext:华夏风云/audio/skill:3",
    enable: "phaseUse",
    usable: 1,
    filter: function (event, player) {
        if (!player.countCards("h")) return false;

        return get.cardPile2(function (card) {
            return card.name == "sha";
        });
    },
    filterTarget: function (card, player, target) {
        return target != player && player.canCompare(target);
    },
    content: function () {
        "step 0"
        event.myWin = 0;
        event.targetWin = 0;
        event.myCards = [];

        var sha = get.cardPile2(function (card) {
            return card.name == "sha";
        });

        if (sha) {
            player.gain(sha, "gain2");
            game.log(player, "从牌堆获得了一张", "#g【杀】");
        }

        "step 1"
        if (!player.isAlive() || !target.isAlive()) {
            event.goto(3);
            return;
        }

        if (!player.countCards("h") || !target.countCards("h") || !player.canCompare(target)) {
            event.goto(3);
            return;
        }

        player.chooseToCompare(target).set("ai", function (card) {
            var current = _status.event.player;
            var compareEvt = _status.event.getParent("chooseToCompare");
            var opponent = null;

            // 准确获取拼点的对手方，无论是发起者还是目标方由AI托管均不会报错
            if (compareEvt) {
                opponent = (current == compareEvt.player ? compareEvt.target : compareEvt.player);
            }
            if (!opponent && _status.event.source && _status.event.source != current) {
                opponent = _status.event.source;
            }

            var num = get.number(card);

            // 安全校验对方是否存在且存活
            if (opponent && typeof opponent.countCards == "function") {
                if (current.countCards("h") <= opponent.countCards("h")) {
                    return num;
                }
            } else if (current.countCards("h") <= 2) {
                return num;
            }

            if (num >= 11) return num - 6;
            return 15 - num;
        });

        "step 2"
        var myCard = null;

        if (result.player) {
            myCard = result.player;
        } else if (result.card1) {
            myCard = result.card1;
        }

        if (myCard) {
            event.myCards.push(myCard);
        }

        if (result.winner) {
            if (result.winner == player) {
                event.myWin++;
                game.log(player, "本次", "#g【猘争】", "拼点胜利");
            } else if (result.winner == target) {
                event.targetWin++;
                game.log(target, "本次", "#g【猘争】", "拼点胜利");
            }
        } else if (result.bool) {
            event.myWin++;
            game.log(player, "本次", "#g【猘争】", "拼点胜利");
        } else if (result.tie) {
            game.log("本次", "#g【猘争】", "拼点平局");
        } else {
            event.targetWin++;
            game.log(target, "本次", "#g【猘争】", "拼点胜利");
        }

        event.goto(1);

        "step 3"
        game.log(player, "因", "#g【猘争】", "拼赢", "#y" + event.myWin, "次；", target, "拼赢", "#y" + event.targetWin, "次");

        if (event.myWin > event.targetWin) {
            event.resultType = "player";
        } else if (event.targetWin > event.myWin) {
            event.resultType = "target";
        } else {
            event.resultType = "tie";
        }

        "step 4"
        if (event.resultType == "player") {
            var cards = [];
            for (var i = 0; i < event.myCards.length; i++) {
                var card = event.myCards[i];
                if (card && ["o", "d"].contains(get.position(card))) {
                    cards.push(card);
                }
            }

            if (cards.length) {
                player.gain(cards, "gain2");
                game.log(player, "收回了所有自己的", "#g【猘争】", "拼点牌");
            }

            var stat = player.getStat("skill");
            if (stat && stat.hx_zhizheng) {
                stat.hx_zhizheng = 0;
            }

            game.log(player, "重置了", "#g【猘争】");
            event.finish();
            return;
        }

        if (event.resultType == "target") {
            event.duelNum = event.targetWin;
            game.log(target, "视为对", player, "使用", "#y" + event.duelNum, "张", "#g【决斗】");
        } else {
            game.log("#g【猘争】", "拼赢次数相同，没有后续效果");
            event.finish();
            return;
        }

        "step 5"
        if (event.duelNum <= 0 || !player.isAlive() || !target.isAlive()) {
            event.finish();
            return;
        }

        event.duelNum--;

        target.useCard({
            name: "juedou",
            isCard: true,
        }, player, false);

        "step 6"
        if (event.duelNum > 0) {
            event.goto(5);
        }
    },
    ai: {
        order: 7,
        result: {
            target: function (player, target) {
                if (!player.canCompare(target)) return 0;

                var ph = player.countCards("h");
                var th = target.countCards("h");

                if (ph > th) return -1.5;
                if (ph < th) return 0.5;
                return -0.5;
            },
        },
    },
    skill_id: "hx_zhizheng",
    _priority: 0,
},


