    //韦孝宽
    
    hun_qiaozhan: {
    audio: "ext:华夏风云/audio/skill:3",
    group: ["hun_qiaozhan_disable"],
    trigger: {
        player: ["gainAfter", "loseAfter"],
    },
    locked: false,
    filter(event, player) {
        if (player.storage.hun_qiaozhan_disabled) return false;
        if (!player.isIn()) return false;

        // 装装备两次修复：同一次手牌变化（150ms内 + 同触发名 + 同手牌数）只触发一次
        var now = Date.now();
        var tn = (event && event.triggername) || "";
        var cnt = player.countCards("h");
        var last = player.storage.hun_qiaozhan_lastTrigger;
        if (last && (now - last.t) < 150 && last.tn === tn && last.cnt === cnt) {
            return false;
        }

        var myCount = cnt;
        var players = game.filterPlayer();
        var isMin = true, isMax = true;
        for (var i = 0; i < players.length; i++) {
            var p = players[i];
            if (p === player) continue;
            if (!p.isIn()) continue;
            var cnt2 = p.countCards("h");
            if (cnt2 < myCount) isMin = false;
            if (cnt2 > myCount) isMax = false;
        }
        if (!isMin && !isMax) return false;
        return game.hasPlayer(function (t) {
            return t !== player && t.isIn() && !t.isDying();
        });
    },
    async content(event, trigger, player) {
        // 进入 content 立刻打"本次触发"时间戳，后面挨着来的重复事件在 filter 里被拦
        var now2 = Date.now();
        var tn2 = (event && event.triggername) || "";
        var cnt2 = player.countCards("h");
        player.storage.hun_qiaozhan_lastTrigger = { t: now2, tn: tn2, cnt: cnt2 };

        var myCount = cnt2;
        var players = game.filterPlayer();
        var isMin = true, isMax = true;
        for (var i = 0; i < players.length; i++) {
            var p = players[i];
            if (p === player) continue;
            if (!p.isIn()) continue;
            var cnt3 = p.countCards("h");
            if (cnt3 < myCount) isMin = false;
            if (cnt3 > myCount) isMax = false;
        }
        var tag = isMin ? "最少" : "最多";

        // 发动先锁：防 damage 内部（求桃用桃）嵌套再触发
        player.storage.hun_qiaozhan_disabled = true;

        var result = await player
            .chooseTarget("巧战：手牌数" + tag + "（" + myCount + "张），选择一名角色分配1点伤害", false)
            .set("filterTarget", function (card, pl, tgt) {
                return tgt !== player && tgt.isIn() && !tgt.isDying();
            })
            .set("ai", function (tgt) {
                if (tgt === player) return -999;
                var att = get.attitude(player, tgt);
                if (att >= 0) return att - 5;
                var hpEffect = (4 - Math.min(3, tgt.hp)) * 3;
                return 10 + hpEffect + get.damageEffect(tgt, player, player);
            })
            .forResult();

        if (!result || !result.bool || !result.targets || !result.targets.length) {
            player.storage.hun_qiaozhan_disabled = false;
            return;
        }

        var target = result.targets[0];
        player.line(target, "red");

        var dyingBefore = game.getGlobalHistory("everything", function (evt) {
            return evt.name == "dying";
        }).length;

        await target.damage(player, 1, null, null, "hun_qiaozhan");

        var dyingAfter = game.getGlobalHistory("everything", function (evt) {
            return evt.name == "dying";
        }).length;

        if (dyingAfter > dyingBefore) {
            player.tempBanSkill("hun_qiaozhan");
            player.popup("巧战·本回合失效", "red");
            game.log(player, "的技能【巧战】因令角色进入濒死状态，本回合失效");
        } else {
            player.storage.hun_qiaozhan_disabled = false;
        }
    },
    subSkill: {
        disable: {
            trigger: {
                global: "phaseBegin",
            },
            forced: true,
            silent: true,
            popup: false,
            async content(event, trigger, player) {
                player.storage.hun_qiaozhan_disabled = false;
                try { delete player.storage.hun_qiaozhan_lastTrigger; } catch (e) {
                    try { player.storage.hun_qiaozhan_lastTrigger = null; } catch (e2) {}
                }
                try { player.tempBanSkillRemove("hun_qiaozhan"); } catch (e) {}
            },
            "skill_id": "hun_qiaozhan_disable",
            sub: true,
            sourceSkill: "hun_qiaozhan",
            "_priority": 1,
        },
    },
    ai: {
        order: 3,
        result: {
            target: 1,
        },
    },
    "skill_id": "hun_qiaozhan",
    "_priority": 0,
},

