	hx_shuangchen: {
	audio: "ext:华夏风云/audio/skill:3",
	forced: true,
	trigger: {
		global: ["loseAfter", "loseAsyncAfter", "cardsDiscardAfter", "phaseBegin"],
	},
	filter(event, player) {
		if (event.name == "phaseBegin") return true;
		// 排除装备等（牌去了装备区不是弃牌堆）
		if (event.to && event.to != "d") return false;
		const cards = (event.cards || []).filterInD("d");
		if (!cards.length) return false;
		// 判断失牌者是否为自己（兼容多种事件结构）
		let loser = event.player || event.source;
		if (!loser) {
			// cardsDiscard事件可能需要从父事件链获取玩家
			let p = event.getParent();
			let depth = 0;
			while (p && !loser && depth < 10) {
				loser = p.player || p.source;
				p = p.getParent();
				depth++;
			}
		}
		return loser && loser.name === player.name;
	},
	async content(event, trigger, player) {
		if (trigger.name == "phaseBegin") {
			player.storage.hx_shuangchen_num = 0;
			return;
		}
		const cards = (trigger.cards || []).filterInD("d");
		const gain = [];
		for (const card of cards) {
			player.storage.hx_shuangchen_num = (player.storage.hx_shuangchen_num || 0) + 1;
			if (player.storage.hx_shuangchen_num % 2 == 0) gain.push(card);
		}
		if (gain.length) {
			game.log(player, "获得", gain);
			await player.gain(gain, "gain2");
		}
		},
	},


