             hx_pingjiang: {
	audio: "ext:华夏风云/audio/skill:2",
	trigger: {
		global: "phaseBegin",
	},
	forced: true,
	getModeList() {
		const list = game.filterPlayer().map((current) => current.countCards("h"));
		const map = {};
		let max = 0;
		const modes = [];

		for (const num of list) {
			map[num] = (map[num] || 0) + 1;
			if (map[num] > max) {
				max = map[num];
			}
		}

		if (max <= 1) {
			return [];
		}

		for (const num in map) {
			if (map[num] === max) {
				modes.push(Number(num));
			}
		}

		return modes.sort((a, b) => a - b);
	},
	filter(event, player) {
		const zhlist = lib.skill.hx_pingjiang.getModeList();

		if (!zhlist.length) {
			return false;
		}

		return !zhlist.includes(player.countCards("h"));
	},
	async content(event, trigger, player) {
		const zhlist = lib.skill.hx_pingjiang.getModeList();

		if (!zhlist.length) {
			return;
		}

		const result = await player
			.chooseControl(zhlist.map(String))
			.set("prompt", "平江：将手牌数调整为场上一个众数")
			.set("ai", () => {
				const controls = _status.event.controls || [];
				const player = _status.event.player;
				if (!controls.length) {
					return "cancel2";
				}
				const num = player.countCards("h");
				return controls
					.slice()
					.sort((a, b) => Math.abs(Number(a) - num) - Math.abs(Number(b) - num))[0];
			})
			.forResult();

		if (!result || !result.control) {
			return;
		}

		const control = Number(result.control);
		const zhnum = player.countCards("h") - control;
		let topx = [];

		if (zhnum > 0) {
			const discardResult = await player
				.chooseToDiscard(`平江：弃置${zhnum}张手牌`, zhnum, "h", true)
				.set("ai", (card) => 6 - get.value(card))
				.forResult();

			if (discardResult?.cards?.length) {
				topx = discardResult.cards.filter((card) => get.position(card) === "d");
			}
		} else if (zhnum < 0) {
			const num = -zhnum;
			await player.draw(num);

			const gainHistory = player.getHistory("gain", (evt) => {
				return evt.getParent(2) === event;
			})[0];

			if (gainHistory?.cards?.length) {
				topx = gainHistory.cards.slice();
			}
		}

		if (topx.length) {
			const moveResult = await player
				.chooseToMove("平江：将其中任意张牌置于牌堆底")
				.set("list", [
					["此次获得或失去的牌", topx],
					["牌堆底"],
				])
				.set("processAI", function (list) {
					const cards = list[0][1].slice();
					const player = _status.event.player;
					const zhnum = _status.event.zhnum;

					if (zhnum > 0) {
						cards.sort((a, b) => {
							return get.type2(a) === "basic" && get.type2(b) !== "basic"
								? -1
								: get.type2(a) !== "basic" && get.type2(b) === "basic"
									? 1
									: get.value(a) - get.value(b);
						});
						return [[], cards];
					}

					const bottom = cards.filter((card) => get.value(card) <= 6);
					const gain = cards.filter((card) => get.value(card) > 6);

					bottom.sort((a, b) => {
						return get.type2(a) === "basic" && get.type2(b) !== "basic"
							? -1
							: get.type2(a) !== "basic" && get.type2(b) === "basic"
								? 1
								: get.value(a) - get.value(b);
					});

					return [gain, bottom];
				})
				.set("zhnum", zhnum)
				.forResult();

			if (moveResult?.moved?.[1]?.length) {
				const cards = moveResult.moved[1].slice();

				game.log(player, "将", cards, "置于了牌堆底");
				player.$throw(cards.length, 1000);

				if (zhnum < 0) {
					await player.lose(cards, ui.cardPile);
				} else {
					for (const card of cards) {
						card.fix();
						ui.cardPile.appendChild(card);
					}
				}

				game.updateRoundNumber();
			}
		}

		if (game.hasPlayer((current) => player.canUse({ name: "dz_mantianguohai" }, current))) {
			await player.chooseUseTarget({ name: "dz_mantianguohai", isCard: true }, true);
		}
	},
},


