hx_xiaomeng: {
    audio: "ext:华夏风云/audio/skill:3",
    group: ["hx_xiaomeng_damage", "hx_xiaomeng_clear"],
    trigger: {
        player: "useCard1",
    },
    filter(event, player) {
        if (!event.card || event.card.name != "sha") return false;
        if (player.storage.hx_xiaomeng_used) return false;
        // 仅在自己的回合（出牌阶段）触发，阵斩等他人回合的虚拟杀不触发
        if (_status.currentPhase != player) return false;
        return game.hasPlayer(target =>
            target != player && target.isIn() && player.inRange(target)
        );
    },
    check(event, player) {
        return game.countPlayer(target =>
            target != player && target.isIn() && player.inRange(target)
        ) >= 2;
    },
    async content(event, trigger, player) {
        player.storage.hx_xiaomeng_used = true;

        // 获取攻击范围内所有其他存活角色
        const allTargets = game.filterPlayer(target =>
            target != player && target.isIn() && player.inRange(target)
        );

        // 计算最小体力值与最小手牌数
        let minHp = Infinity, minCards = Infinity;
        for (const t of allTargets) {
            if (t.hp < minHp) minHp = t.hp;
            if (t.countCards("h") < minCards) minCards = t.countCards("h");
        }

        const minHpTargets = allTargets.filter(t => t.hp == minHp);
        const minCardTargets = allTargets.filter(t => t.countCards("h") == minCards);

        // 存储最小体力值目标的【名称字符串】（避免Player对象比较失败）
        player.storage.hx_xiaomeng_hp = minHpTargets.map(t => t.name);

        // 构建目标列表：依次加入所有角色
        // 手牌数最少的角色紧随其后额外加入一次 → 额外结算一次
        const newTargets = [];
        for (const t of allTargets) {
            newTargets.push(t);
            if (minCardTargets.includes(t)) {
                newTargets.push(t);
            }
        }
        trigger.targets = newTargets;

        if (minHpTargets.length) {
            game.log(player, "令体力值最小的", minHpTargets, "受到的伤害+1");
        }
        if (minCardTargets.length) {
            game.log(player, "令手牌数最少的", minCardTargets, "额外结算一次");
        }
    },
    subSkill: {
        // ===== 体力值最小的角色受到伤害+1 =====
        damage: {
            trigger: {
                source: "damageBegin3",
            },
            forced: true,
            popup: false,
            filter(event, player) {
                if (!event.card || event.card.name != "sha") return false;
                if (!event.player) return false;
                const list = player.storage.hx_xiaomeng_hp;
                if (!list || !Array.isArray(list)) return false;
                return list.includes(event.player.name);
            },
            content() {
                trigger.num++;
                game.log(player, "令", trigger.player, "受到的伤害+1");
            },
        },
        // ===== 回合结束清除所有标记 =====
        clear: {
            trigger: {
                global: "phaseEnd",
            },
            forced: true,
            popup: false,
            content() {
                delete player.storage.hx_xiaomeng_used;
                delete player.storage.hx_xiaomeng_hp;
            },
        },
    },
    ai: {
        threaten: 1.5,
    },
},

