hx_weishi: {
    audio: "ext:华夏风云/audio/skill:3",
    group: ["hx_weishi_clear"],
    trigger: {
        source: "damageBegin1",
    },
    filter(event, player) {
        if (player.storage.hx_weishi_used) return false;
        // 阵斩的虚拟杀不触发威势
        if (event.card && event.card.hx_zhenzhan) return false;
        // 仅在自己的回合（出牌阶段）触发
        if (_status.currentPhase != player) return false;
        const target = event.player;
        if (!target || target == player) return false;
        // 体力值不少于你 或 手牌数不少于你
        return target.hp >= player.hp || target.countCards("h") >= player.countCards("h");
    },
    check(event, player) {
        const target = event.player;
        const hpCond = target.hp >= player.hp;
        const cardCond = target.countCards("h") >= player.countCards("h");
        let drawCount = 0;
        if (hpCond) drawCount = Math.max(drawCount, target.countCards("h"));
        if (cardCond) drawCount = Math.max(drawCount, target.hp);
        return drawCount > 0;
    },
    async content(event, trigger, player) {
        const target = trigger.player;
        player.storage.hx_weishi_used = true;

        const hpCond = target.hp >= player.hp;       // 体力值不少于你
        const cardCond = target.countCards("h") >= player.countCards("h"); // 手牌数不少于你

        // 两个条件可以同时触发，摸牌数累加
        let drawCount = 0;
        if (hpCond) drawCount += target.countCards("h");   // 体力值不少于你 → 摸等同于其手牌数
        if (cardCond) drawCount += target.hp;               // 手牌数不少于你 → 摸等同于其体力值

        // 防止伤害
        trigger.cancel();

        // 记录摸牌原因
        let reasons = [];
        if (hpCond) reasons.push(get.translation(target) + "的体力值不少于自己，摸等同于其手牌数的牌");
        if (cardCond) reasons.push(get.translation(target) + "的手牌数不少于自己，摸等同于其体力值的牌");
        game.log(player, "发动了", "#g【威势】", "，" + reasons.join("；"));

        // 摸牌（框架会自动记录摸牌日志）
        await player.draw(drawCount);
    },
    subSkill: {
        // ===== 回合结束后清除使用标记 =====
        clear: {
            trigger: {
                global: "phaseAfter",
            },
            forced: true,
            popup: false,
            content() {
                delete player.storage.hx_weishi_used;
            },
        },
    },
    ai: {
        threaten: 1.5,
    },
},


