    //王玄策

    hx_jspj: {
	nobracket: true,
	audio: "ext:华夏风云/audio/skill:2",
	trigger: {
		player: "loseAfter",
		global: ["loseAsyncAfter", "cardsDiscardAfter"],
	},
	direct: true,
	filter(event, player) {
		return lib.skill.hx_jspj.getBasicCards(event, player).length > 0;
	},
	getBasicCards(event, player) {
		let cards = [];

		if (event.getd) {
			const list = event.getd(player, "cards2");
			if (list && list.length) {
				cards.addArray(list);
			}
		}

		if (event.getl) {
			const evt = event.getl(player);
			if (evt && evt.cards2 && evt.cards2.length) {
				cards.addArray(evt.cards2);
			}
		}

		if (event.player === player && event.cards2 && event.cards2.length) {
			cards.addArray(event.cards2);
		}

		cards = cards.filter((card) => {
			return get.position(card, true) === "d" && get.type(card, player) === "basic";
		});

		return cards;
	},
	getPrompt(index) {
		switch (index) {
			case 1:
				return "移动场上的一张牌";
			case 2:
				return "令一名其他角色弃置一张手牌";
			case 3:
				return "令一名角色回复1点体力";
			case 4:
				return "你摸牌至体力上限";
			default:
				return "";
		}
	},
	canDo(index, player) {
		switch (index) {
			case 1:
				return player.canMoveCard(null, true);
			case 2:
				return game.hasPlayer((target) => {
					return target !== player && target.countCards("h") > 0;
				});
			case 3:
				return game.hasPlayer((target) => {
					return target.isDamaged();
				});
			case 4:
				return player.countCards("h") < player.maxHp;
			default:
				return false;
		}
	},
	async doEffect(index, player) {
		switch (index) {
			case 1: {
				await player.moveCard(true);
				break;
			}

			case 2: {
				const result = await player
					.chooseTarget(get.prompt("hx_jspj"), "令一名其他角色弃置一张手牌", true, (card, player, target) => {
						return target !== player && target.countCards("h") > 0;
					})
					.set("ai", (target) => {
						return -get.attitude(_status.event.player, target);
					})
					.forResult();

				if (result?.bool && result.targets?.length) {
					await result.targets[0].chooseToDiscard("h", true);
				}
				break;
			}

			case 3: {
				const result = await player
					.chooseTarget(get.prompt("hx_jspj"), "令一名角色回复1点体力", true, (card, player, target) => {
						return target.isDamaged();
					})
					.set("ai", (target) => {
						return get.recoverEffect(target, _status.event.player, _status.event.player);
					})
					.forResult();

				if (result?.bool && result.targets?.length) {
					await result.targets[0].recover();
				}
				break;
			}

			case 4: {
				await player.drawTo(player.maxHp);
				break;
			}
		}
	},
	async content(event, trigger, player) {
		const cards = lib.skill.hx_jspj.getBasicCards(trigger, player);

		if (!cards.length) {
			return;
		}

		player.storage.hx_jspj_counter ??= 0;

		for (const card of cards) {
			player.storage.hx_jspj_counter++;

			if (player.storage.hx_jspj_counter > 4) {
				player.storage.hx_jspj_counter = 1;
			}

			const index = player.storage.hx_jspj_counter;
			const prompt = lib.skill.hx_jspj.getPrompt(index);

			if (!prompt) {
				continue;
			}

			if (!lib.skill.hx_jspj.canDo(index, player)) {
				if (index === 4) {
					player.storage.hx_jspj_counter = 0;
				}
				continue;
			}

			const result = await player
				.chooseBool(`###${get.prompt("hx_jspj")}###你的基本牌进入弃牌堆，是否执行第${index}项：${prompt}？`)
				.set("ai", () => {
					return true;
				})
				.forResult();

			if (result?.bool) {
				player.logSkill("hx_jspj");
				await lib.skill.hx_jspj.doEffect(index, player);
			}

			if (index === 4) {
				player.storage.hx_jspj_counter = 0;
			}
		}
	},
	group: "hx_jspj_clear",
	subSkill: {
		clear: {
			trigger: {
				global: "roundStart",
			},
			forced: true,
			silent: true,
			firstDo: true,
			content(event, trigger, player) {
				delete player.storage.hx_jspj_counter;
			},
		},
	},
	onremove(player) {
		delete player.storage.hx_jspj_counter;
	},
},


