    //魂李世民
    
    hun_shenwu: {
	audio: "ext:华夏风云/audio/skill:3",
	trigger: {
		player: [
			"damageBefore",
			"loseHpBefore",
			"turnOverBefore",
			"turnoverBefore",
			"loseMaxHpBefore",
			"maxHpLoseBefore",
			"linkBefore",
			"tieBefore",
			"chainBefore",
		],
	},
	filter(event, player) {
		const source = event.source;

		// 翻面等事件可能没有source，通过父事件链找来源
		let p = event.getParent();
		let depth = 0;
		let fromSkill = false;
		let skillName = null;
		let skillPlayer = null;
		while (p && depth < 15) {
			if (p.name == "useCard" || p.name == "useCardTo") return false;
			if (p.name == "useSkill") {
				fromSkill = true;
				skillName = p.skill || p.name1;
				skillPlayer = p.player || p.source;
				break;
			}
			if (p.skill) {
				fromSkill = true;
				skillName = p.skill;
				skillPlayer = p.player || p.source;
				break;
			}
			try { p = p.getParent(); } catch(e) { break; }
			depth++;
		}
		if (!fromSkill) return false;

		// 防递归
		if (skillName == "hun_shenwu") return false;

		// 技能发动者不能是自己
		if (skillPlayer && skillPlayer == player) return false;

		// 把找到的技能发动者存到事件上，方便content用
		event._buyiming_source = source || skillPlayer;

		return true;
	},
	check(event, player) {
		return true;
	},
	async content(event, trigger, player) {
		const source = trigger._buyiming_source || trigger.source;
		if (!source || source == player) return;

		game.log(player, "反弹了", source, "的技能效果");

		// 转移目标：把效果转移给来源
		if (trigger.player == player) {
			trigger.player = source;
		}
		if (trigger.target == player) {
			trigger.target = source;
		}
	},
},

