           //段志玄
           
           "hx_duoqi": {
    audio: 2,
    logAudio: index => (typeof index === "number" ? "hx_duoqi" + index + ".mp3" : 2),
    popup: true,
    frequent: false,
    forced: false,
    locked: false,

    trigger: {
        global: ["phaseEnd", "damageSource"]
    },

    filter(event, player) {
        let other = null;
        if (event.source) {
            if (!event.source || event.source === player) return false;
            if (!event.source.isIn()) return false;
            if (event.player && !event.player.isIn()) return false;
            other = event.source;
        } else {
            other = event.player || _status.current;
            if (!other) return false;
            if (other === player) return false;
            if (!other.isIn()) return false;
        }
        return other.countCards("he") > 0;
    },

    check(event, player) {
        let other = event.source || event.player || _status.current;
        if (!other || !other.isIn()) return false;
        if (other.countCards("h") <= 0) return true;
        if (get.attitude(player, other) >= 3) return false;
        return true;
    },

    logTarget: "source",
    prompt2: "获得其 1 张牌，然后其可将一张手牌当【决斗】对你使用",

    async content(event, trigger, player) {
        "step 0";
        let target = trigger.source || trigger.player || _status.current;
        if (!target) return;
        if (target === player) return;
        if (!target.isIn()) return;

        // 引擎自动打：X 对 Y 发动了【夺气】
        await player.gainPlayerCard(target, "he", true);
        // 引擎自动打：X 从 Y 获得了 顺手牵羊【花色点数】

        "step 1";
        if (!target.isIn() || target.countCards("h") <= 0) return;

        const { links } = await target.chooseButton(
            [
                "【夺气】" + get.translation(player) + " 获得了你的一张牌，你是否要将一张手牌当【决斗】对其使用？",
                [
                    [
                        ["yes", "是"],
                        ["no", "否"]
                    ],
                    "textbutton"
                ]
            ],
            true
        ).forResult();
        if (!links || links[0] !== "yes") return;

        "step 2";

        const { links: cards } = await target.chooseButton(
            [
                "【夺气】请选择一张手牌当作【决斗】对" + get.translation(player) + "使用",
                target.getCards("h")
            ],
            true
        ).forResult();
        if (!cards || !cards.length) return;

        const theCard = cards[0];
        const juedou = get.autoViewAs({ name: "juedou", isCard: true }, [theCard]);

        // —— 只保留转化决斗这条日志（引擎不会自动生成）——
        game.log(
            get.translation(target) + " 通过【夺气】将 " + get.translation(theCard) +
            ' 当作 <span data-card="juedou">【决斗】</span> 对 ' + get.translation(player) + " 使用"
        );

        await target.chooseUseTarget(juedou, [theCard])
            .set("targets", [player])
            .set("forced", true)
            .set("autoConfirm", true)
            .set("complexTarget", false)
            .set("targetRequired", 1)
            .set("manual", false)
            .set("filterTarget", function (card, _p, t) {
                return t === player;
            });

        await game.delayx();
    },

    intro: {
        content() {
            return "一名其他角色的回合结束时或一名其他角色造成伤害时，你可以获得其1张牌，然后其可以将一张手牌当【决斗】对你使用。";
        }
    },

    skill_id: "hx_duoqi",
    _priority: 0,
},
    
    
