        hx_zhaomingli: {
	audio: "ext:华夏风云/audio/skill:3",
	trigger: {
		global: "phaseBefore",
		player: "enterGame",
	},
	forced: true,
	filter: function(event, player) {
		return event.name != "phase" || game.phaseNumber == 0;
	},
	content: function() {
		var cards = player.getCards("h");
		if (cards.length) {
			player.addGaintag(cards, "hx_zhaomingli_tag");
			game.log(player, "将初始手牌标记为了“昭”牌");
		}
	},
	group: ["hx_zhaomingli_lose"],
	subSkill: {
		"lose": {
			audio: "hx_zhaomingli",
			trigger: {
				player: "loseAfter"
			},
			direct: true,
			filter: function(event, player) {
				if (!event.gaintag_map) return false;
				for (var i in event.gaintag_map) {
					if (event.gaintag_map[i].includes("hx_zhaomingli_tag")) return true;
				}
				return false;
			},
			content: function() {
				'step 0'
				var count = 0;
				for (var i in trigger.gaintag_map) {
					if (trigger.gaintag_map[i].includes("hx_zhaomingli_tag")) {
						count++;
					}
				}
				event.count = count;
				
				'step 1'
				if (event.count <= 0) {
					event.finish();
					return;
				}
				event.count--;
				
				var unmarked = player.getCards('h', function(card) {
					return !card.hasGaintag("hx_zhaomingli_tag");
				});
				
				var choices = [];
				if (unmarked.length >= 2) {
					choices.push("标记两张手牌");
					choices.push("摸一张牌");
				} else {
					choices.push("摸一张牌");
				}
				choices.push("cancel2");

				player.chooseControl(choices).set("prompt", "昭鸣：请选择一项效果（剩余 " + (event.count + 1) + " 次）").set("ai", function() {
					var p = _status.event.player;
					var un = p.getCards('h', function(c) {
						return !c.hasGaintag("hx_zhaomingli_tag");
					});
					if (un.length >= 2) {
						return "标记两张手牌";
					}
					return "摸一张牌";
				});
				
				'step 2'
				if (result.control && result.control !== "cancel2") {
					player.logSkill("hx_zhaomingli");
					if (result.control === "摸一张牌") {
						player.draw();
						event.goto(4);
					} else if (result.control === "标记两张手牌") {
						player.chooseCard('h', 2, '选择2张手牌标记为“昭”牌', function(card) {
							return !card.hasGaintag("hx_zhaomingli_tag");
						}).set('ai', function(card) {
							return 1;
						});
					}
				} else {
					event.goto(4);
				}
				
				'step 3'
				if (result.bool && result.cards && result.cards.length) {
					player.addGaintag(result.cards, "hx_zhaomingli_tag");
					game.log(player, '将两张手牌标记为了“昭”牌');
				}
				
				'step 4'
				if (event.count > 0) {
					event.goto(1);
				}
			}
		}
	}
},


    //魂王猛

