    hun_xuhuai: {
        group: ["hun_xuhuai1", "hun_xuhuai2", "hun_xuhuai3"],
        direct: true,
        init: (player) => {
            player.storage.hun_xuhuai = []
        },
        intro: {
            content: "cards",
        },
        marktext: "桓",
        mark: true,
        trigger: {
            global: "gameStart"
        },
        content: function () {
            function gainRandomTrickCards(player) {

                const allTricks = lib.inpile.filter(cardName =>
                    cardName && get.type(cardName) === "trick"
                );
                if (allTricks.length < 12) {
                    game.log(`牌堆中只有 ${allTricks.length} 张锦囊牌，将返回所有可用牌`);
                }
                const selectedTricks = [];
                const nameSet = new Set();
                const shuffled = [...allTricks].sort(() => Math.random() - 0.5);

                for (const trickName of shuffled) {
                    if (!nameSet.has(trickName)) {
                        nameSet.add(trickName);
                        selectedTricks.push(trickName);
                        if (selectedTricks.length >= 12) break;
                    }
                }
                const createdCards = selectedTricks.map(trickName => {
                    const card = game.createCard({
                        name: trickName,
                        suit: lib.suit.randomGet(),
                        number: Math.floor(Math.random() * 13) + 1
                    });
                    return card;
                });
                player.storage.hun_xuhuai = player.storage.hun_xuhuai.concat(createdCards);
                player.$give(createdCards, player, false);
                player.syncStorage("hun_xuhuai");
                game.log(player, `玩家已将 ${createdCards.length} 张不同牌名的锦囊牌置于武将牌称为桓`);

            }
            gainRandomTrickCards(player);
        }
    },


