    hun_yiai: {
    trigger: {
        player: "changeHp"
    },
    async content(event, trigger, player) {
        var handCards = player.getCards("h");
        if (!handCards.length) return;

        // 统计每种花色的牌数
        var suitMap = {};
        for (var i = 0; i < handCards.length; i++) {
            var s = get.suit(handCards[i]);
            if (!suitMap[s]) suitMap[s] = [];
            suitMap[s].push(handCards[i]);
        }
        var suitList = Object.keys(suitMap);
        if (!suitList.length) return;

        // AI优先弃置最少的，且弃置数不超过3
        var bestSuit = suitList[0];
        var bestCount = suitMap[bestSuit].length;
        for (var k = 1; k < suitList.length; k++) {
            if (suitMap[suitList[k]].length < bestCount) {
                bestCount = suitMap[suitList[k]].length;
                bestSuit = suitList[k];
            }
        }

        // 如果弃置数大于3就不发动
        if (bestCount > 3) return;

        // 玩家手动选花色
        if (!event.isDummy) {
            var suitRes = await player.chooseControl(suitList)
                .set("prompt", "遗爱：选择一种花色，弃置该花色的所有手牌")
                .set("ai", function() {
                    return bestSuit;
                })
                .forResult();
            var selectedSuit = suitRes.control;
        } else {
            var selectedSuit = bestSuit;
        }

        var suitCards = suitMap[selectedSuit] || [];
        if (!suitCards.length) return;

        player.discard(suitCards);
        game.log(player, "发动【遗爱】，弃置了", get.translation(selectedSuit), "花色的", suitCards.length, "张牌");

        var cardPile = ui.cardPile;
        var differentSuitCards = [];
        for (var m = 0; m < cardPile.childElementCount; m++) {
            var card = cardPile.childNodes[m];
            if (card && get.suit(card) !== selectedSuit) {
                differentSuitCards.push(card);
            }
        }

        var maxCards = Math.min(3, differentSuitCards.length);
        if (maxCards > 0) {
            var cardsToGain = [];
            var availableIndices = [];
            for (var n = 0; n < differentSuitCards.length; n++) availableIndices.push(n);

            for (var p = 0; p < maxCards; p++) {
                var randomIndex = Math.floor(Math.random() * availableIndices.length);
                var selectedIndex = availableIndices[randomIndex];
                cardsToGain.push(differentSuitCards[selectedIndex]);
                availableIndices.splice(randomIndex, 1);
            }

            player.gain(cardsToGain, "gain2");
            game.log(player, "从牌堆获得了", cardsToGain.length, "张不同花色的牌");
        } else {
            game.log("牌堆中没有与", get.translation(selectedSuit), "花色不同的牌");
        }
    },
},


