    hun_quanzhi: {
    audio: "ext:华夏风云/audio/skill:2",
    trigger: {
        global: "phaseBefore",
        player: "enterGame",
    },
    forced: true,
    filter(event, player) {
        return event.name != "phase" || game.phaseNumber == 0;
    },
    async content(event, trigger, player) {
        const cards = [];
        for (let i = 0; i < ui.cardPile.childNodes.length; i++) {
            const card = ui.cardPile.childNodes[i];
            if (get.type(card) != "trick") continue;
            if (!cards.some(cardx => cardx.name == card.name)) {
                cards.push(card);
            }
        }
        if (!cards.length) return;
        const next = player.addToExpansion(cards, player, "give");
        next.gaintag.add(event.name);
        await next;
    },
    marktext: "燕",
    intro: {
        content: "expansion",
        markcount: "expansion",
    },
    onremove(player, skill) {
        const cards = player.getExpansions(skill);
        if (cards.length) {
            player.loseToDiscardpile(cards);
        }
    },
    group: ["hun_quanzhi_change", "hun_quanzhi_use"],
    subSkill: {
        tag: {
            name: "燕",
        },
        change: {
            trigger: {
                global: ["loseEnd", "loseAsyncEnd", "gainEnd", "addToExpansionEnd", "equipEnd", "addJudgeEnd"],
            },
            silent: true,
            charlotte: true,
            forceDie: true,
            filter(event, player) {
                if (event.name == "addToExpansion") return event.gaintag.includes("hun_quanzhi");
                if (!event.player) return false;
                const evt = event.getl?.(event.player);
                if (!evt || !evt.xs || !evt.xs.length) {
                    return false;
                }
                return Object.values(event.gaintag_map || {}).flat().includes("hun_quanzhi");
            },
            async content(event, trigger, player) {
                const toAdd = [],
                    toRemove = trigger.getl?.(player)?.xs || [];
                if (trigger.name == "addToExpansion") {
                    toAdd.addArray(trigger.cards);
                }
                event.set("toAdd", toAdd);
                event.set("toRemove", toRemove);
                await event.trigger("hun_quanzhiChange");
            },
        },
        use: {
            init(player, skill) {
                const toRemove = player.getCards("s", card => card.hasGaintag("hun_quanzhi_tag"));
                game.deleteFakeCards(toRemove);
                const cards = game.createFakeCards(player.getExpansions("hun_quanzhi"));
                player.directgains(cards, null, "hun_quanzhi_tag");
            },
            onremove(player, skill) {
                const toRemove = player.getCards("s", card => card.hasGaintag("hun_quanzhi_tag"));
                game.deleteFakeCards(toRemove);
            },
            forced: true,
            popup: false,
            delay: false,
            charlotte: true,
            trigger: {
                player: ["useCardBefore", "respondBefore", "hun_quanzhiChange"],
            },
            filter(event, player) {
                if (["useCard", "respond"].includes(event.name)) {
                    const cards = player.getCards("s", card => card.hasGaintag("hun_quanzhi_tag"));
                    return event.cards && event.cards.some(card => cards.includes(card));
                }
                return true;
            },
            async content(event, trigger, player) {
                const tag = "hun_quanzhi_tag";
                if (["useCard", "respond"].includes(trigger.name)) {
                    trigger.set("hun_quanzhi", true);
                    const real = player.getExpansions("hun_quanzhi");
                    for (let i = 0; i < trigger.cards.length; i++) {
                        const card = trigger.cards[i];
                        const cardx = real.find(cardx => cardx.cardid == card._cardid);
                        if (cardx) {
                            trigger.cards[i] = cardx;
                            trigger.card.cards[i] = cardx;
                            trigger.throw = false;
                            get.owner(cardx)?.$throw(cardx);
                        }
                    }
                } else {
                    game.deleteFakeCards(player.getCards("s", card => trigger.toRemove.find(cardx => cardx.cardid == card._cardid)));
                    player.directgains(game.createFakeCards(trigger.toAdd), null, tag);
                }
            },
        },
    },
},

