    hx_xuefanzhu: {
	audio: "ext:华夏风云/audio/skill:2",
	trigger: {
		global: "phaseUseBegin",
	},
	filter(event, player) {
		// 其他角色的出牌阶段，且其有手牌可弃置
		return event.player != player && event.player.countCards("h") > 0;
	},
	async cost(event, trigger, player) {
		var target = trigger.player;
		event.result = await player
			.choosePlayerCard(target, "h", get.prompt(event.skill, target))
			.set("ai", function (button) {
				var card = button.link;
				var owner = get.owner(card);
				var att = get.attitude(_status.event.player, owner);
				// 对友方不发动
				if (att >= 0) return -1;
				var val = get.value(card);
				// 优先弃置非杀牌以触发"获得牌+改阶段"效果
				if (get.name(card, false) != "sha") return val + 10;
				return val;
			})
			.forResult();
	},
	async content(event, trigger, player) {
		var target = trigger.player;
		// 系统将 cost 的 result.cards 复制到 event.cards（非 event.result）
		if (!event.cards || !event.cards.length) return;
		var card = event.cards[0];
		// 弃置其一张手牌（source 为技能拥有者）
		await target.discard(card, player);
		// 若不为【杀】
		if (get.name(card, false) != "sha") {
			// 获得其一张牌
			if (target.countCards("he") > 0) {
				var result2 = await player
					.choosePlayerCard(target, "he", "选择获得" + get.translation(target) + "的一张牌")
					.set("forced", true)
					.set("ai", function (button) {
						return get.value(button.link);
					})
					.forResult();
				if (result2.bool && result2.cards.length) {
					await player.gain(result2.cards, target, "gain2");
				}
			}
			// 其本回合下个主要阶段改为出牌阶段
			var phaseEvent = trigger.getParent("phase");
			if (phaseEvent && phaseEvent.phaseList) {
				var mainPhases = ["phaseJudge", "phaseDraw", "phaseUse", "phaseDiscard"];
				var changed = false;
				for (var i = phaseEvent.num + 1; i < phaseEvent.phaseList.length; i++) {
					var pname = phaseEvent.phaseList[i].split("|")[0];
					if (mainPhases.includes(pname)) {
						phaseEvent.phaseList[i] = "phaseUse";
						changed = true;
						break;
					}
				}
				if (changed) {
					game.log(target, "本回合下个主要阶段改为", "#y出牌阶段");
				}
			}
		}
	},
	ai: {
		threaten: 1.3,
	},
},


    //王文卿

    hx_leijing: {
	audio: "ext:华夏风云/audio/skill:2",
	ai: {
		threaten: 2.9,
	},
	trigger: {
		player: ["loseAfter", "enterGame"],
		global: ["equipAfter", "addJudgeAfter", "gainAfter", "loseAsyncAfter", "addToExpansionAfter", "phaseBefore"],
	},
	forced: true,
	filter(event, player) {
		if (event.name === "enterGame" || event.name === "phase") {
			return (event.name !== "phase" || game.phaseNumber === 0) && player.countCards("h") < 2;
		}

		if (event.name === "gain" && event.player === player) {
			return player.countCards("h") > 2;
		}

		const evt = event.getl ? event.getl(player) : null;
		if (!evt || !evt.hs || !evt.hs.length) {
			return false;
		}

		if (player.countCards("h") >= 2) {
			return false;
		}

		let parent = event;
		for (let i = 0; i < 2; i++) {
			parent = parent.getParent ? parent.getParent("hx_leijing") : null;
			if (!parent || parent.name !== "hx_leijing") {
				return true;
			}
		}

		return false;
	},
	async content(event, trigger, player) {
		const num = 2 - player.countCards("h");

		if (num > 0) {
			await player.draw(num);
			return;
		}

		if (num < 0) {
			const discardNum = -num;
			const discardResult = await player
				.chooseToDiscard(`雷晶：弃置${discardNum}张手牌`, discardNum, "h", true)
				.set("ai", (card) => {
					return 6 - get.value(card);
				})
				.forResult();

			if (!discardResult?.bool) {
				return;
			}

			const targetResult = await player
				.chooseTarget("雷晶：对一名角色造成1点雷电伤害", true)
				.set("ai", (target) => {
					return get.damageEffect(target, _status.event.player, _status.event.player, "thunder");
				})
				.forResult();

			if (targetResult?.bool && targetResult.targets?.length) {
				await targetResult.targets[0].damage("thunder");
			}
		}
	},
},


