    hx_yongliming: {
    limited: true,
    trigger: {
        global: ["gainAfter", "loseAfter", "damageAfter", "recoverAfter", "loseHpAfter"],
    },
    filter(event, player) {
        if (event.player == player) return false;
        if (!event.player.isIn()) return false;

        var target = event.player;
        // 新增前提：目标必须已受伤
        if (target.hp >= target.maxHp) return false;

        var targetHand = target.countCards("h");
        var targetHp = target.hp;
        var players = game.filterPlayer();

        var handMin = true;
        for (var i = 0; i < players.length; i++) {
            var p = players[i];
            if (p === target) continue;
            if (!p.isIn()) continue;
            if (p.countCards("h") <= targetHand) { handMin = false; break; }
        }

        var hpMin = true;
        for (var i = 0; i < players.length; i++) {
            var p = players[i];
            if (p === target) continue;
            if (!p.isIn()) continue;
            if (p.hp <= targetHp) { hpMin = false; break; }
        }

        return handMin || hpMin;
    },
    check(event, player) {
        return get.attitude(player, event.player) > 1;
    },
    async content(event, trigger, player) {
        var target = trigger.player;
        var name1 = target.name1;

        player.awakenSkill(event.name);
        await player.loseHp(1);

        var names = get.gainableCharacters(function (info, name) {
            var translate = get.translation(name);
            return translate.includes("朱") && ["GXS_hun", "GXS_jun"].includes(info.group);
        });
        var list = names.randomGets(3);
        if (!list.length) {
            player.popup("没有符合的武将牌");
            return;
        }

        var result = await player
            .chooseButton(["扶稷：请选择为" + get.translation(target) + "替换的武将牌", [list, "character"]], true)
            .set("ai", function () { return _status.event.list.randomGet(); })
            .set("list", list)
            .forResult();

        if (!result.bool) return;

        await target.reinitCharacter(name1, result.links[0]);
        await game.delay();
        await target.recoverTo(2);
        await game.delay();

        target.insertPhase();
        game.log(target, "获得了一个额外回合");
    },
    "skill_id": "hx_yongliming",
    "_priority": 0,
},


