    hx_wudang: {
        audio: "ext:华夏风云/audio/skill:2",
        enable: ["chooseToUse", "chooseToRespond"],
        hiddenCard(player, name) {
            if (!_status.currentPhase?.isIn() || !_status.currentPhase.countDiscardableCards(player, "he")) {
                return false;
            }
            return get.type(name) === "basic" && !player.getStorage("hx_wudang_used").includes(name);
        },
        filter(event, player) {
            if (event.hx_wudang) {
                return false;
            }
            if (!_status.currentPhase?.isIn() || !_status.currentPhase.countDiscardableCards(player, "he")) {
                return false;
            }
            return get
                .inpileVCardList(info => {
                    const name = info[2];
                    if (get.type(name) !== "basic") {
                        return false;
                    }
                    return !player.getStorage("hx_wudang_used").includes(name);
                })
                .some(card => event.filterCard(new lib.element.VCard({ name: card[2], nature: card[3], isCard: true }), player, event));
        },
        chooseButton: {
            dialog(event, player) {
                return ui.create.dialog("武当", [get.inpileVCardList(info => get.type(info[2]) === "basic"), "vcard"]);
            },
            filter(button, player) {
                const event = get.event().getParent();
                if (player.getStorage("hx_wudang_used").includes(button.link[2])) {
                    return false;
                }
                return event.filterCard(new lib.element.VCard({ name: button.link[2], nature: button.link[3], isCard: true }), player, event);
            },
            check(button) {
                const event = get.event().getParent();
                if (event.type !== "phase") {
                    return 1;
                }
                return get.player().getUseValue(new lib.element.VCard({ name: button.link[2], nature: button.link[3], isCard: true }));
            },
            prompt(links, player) {
                let prompt = "弃置" + get.translation(_status.currentPhase);
                prompt += "的一张牌，";
                return `###武当###<div class="text center">` + prompt + "视为使用或打出" + (get.translation(links[0][3]) || "") + "【" + get.translation(links[0][2]) + "】</div>";
            },
            backup(links) {
                return {
                    filterCard: () => false,
                    selectCard: -1,
                    viewAs: {
                        name: links[0][2],
                        nature: links[0][3],
                        isCard: true,
                    },
                    log: false,
                    async precontent(event, trigger, player) {
                        const result = await player.discardPlayerCard(_status.currentPhase, "he", true).forResult();
                        if (result.bool) {
                            player.logSkill("hx_wudang");
                            player.addSkill("hx_wudang_used");
                            player.markAuto("hx_wudang_used", [event.result.card.name]);
                            if (event.result.card.name == "sha") {
                                player.removeSkill("hx_wudang_used");
                            }
                        } else {
                            const evt = event.getParent();
                            evt.set("hx_wudang", true);
                            evt.goto(0);
                        }
                    },
                }
            }
        },
        ai: {
            fireAttack: true,
            respondSha: true,
            respondShan: true,
            skillTagFilter(player, tag, arg) {
                if (arg === "respond") return false;
                return get.info("hx_wudang").hiddenCard(
                    player,
                    (() => {
                        switch (tag) {
                            case "fireAttack":
                                return "sha";
                            default:
                                return tag.slice("respond".length).toLowerCase();
                        }
                    })()
                );
            },
            order(item, player) {
                if (player && _status.event.type === "phase") {
                    let max = 0,
                        names = get.inpileVCardList(info => {
                            const name = info[2];
                            if (get.type(name) !== "basic") return false;
                            return !player.getStorage("hx_wudang_used").includes(name);
                        });
                    names = names.map(namex => new lib.element.VCard({
                        name: namex[2],
                        nature: namex[3]
                    }));
                    names.forEach(card => {
                        if (player.getUseValue(card) > 0) {
                            let temp = get.order(card);
                            if (temp > max) max = temp;
                        }
                    });
                    return max + (max > 0 ? 0.2 : 0);
                }
                return 10;
            },
            result: {
                player(player) {
                    if (_status.event.dying) return get.attitude(player, _status.event.dying);
                    return 1;
                },
            },
        },
        subSkill: {
            backup: {},
            used: {
                charlotte: true,
                onremove: true,
            },
        },
    },

