    hx_tongchou: {
        enable: ["chooseToUse", "chooseToRespond"],
        hiddenCard(player, name) {
            return lib.inpile.includes(name) && get.type(name) == "basic" && player.countCards("hes") > 1;
        },
        getList(event, player) {
            return get.inpileVCardList(info => {
                return info[0] == "basic" && event.filterCard(get.autoViewAs({ name: info[2], nature: info[3] }, "unsure"), player, event);
            })
        },
        filter(event, player) {
            return player.countCards("hes") > 1 && get.info("hx_tongchou").getList(event, player).length > 0;
        },
        chooseButton: {
            dialog(event, player) {
                return ui.create.dialog("xx", [get.info("hx_tongchou").getList(event, player), "vcard"], "hidden");
            },
            check(button) {
                if (_status.event.getParent().type != "phase") {
                    return 1;
                }
                if (button.link[2] == "shan") {
                    return 3;
                }
                var player = _status.event.player;
                if (button.link[2] == "jiu") {
                    if (player.getUseValue({ name: "jiu" }) <= 0) {
                        return 0;
                    }
                    if (player.countCards("h", "sha")) {
                        return player.getUseValue({ name: "jiu" });
                    }
                }
                return player.getUseValue({ name: button.link[2], nature: button.link[3] }) / 4;
            },
            backup(links, player) {
                return {
                    filterCard: true,
                    selectCard: [2, Infinity],
                    popname: true,
                    viewAs: {
                        name: links[0][2],
                        nature: links[0][3],
                    },
                    ai1(card) {
                        return 1 / (get.value(card) || 0.5);
                    },
                    position: "hes",
                }
            },
            prompt(links, player) {
                return `将至少两张牌当作${get.translation(links[0][3] || "")}【${get.translation(links[0][2])}】使用或打出`;
            },
        },
        ai: {
            order(item, player) {
                if (_status.event.type == "phase" && player.getUseValue({ name: "jiu" }, null, true) > 0 && player.countCards("h", "sha")) {
                    return get.order({ name: "jiu" }) + 1;
                }
                return 1;
            },
            respondShan: true,
            respondSha: true,
            skillTagFilter(player) {
                if (player.countCards("he") > 1) {
                    return false;
                }
            },
            save: true,
            result: {
                player(player) {
                    if (_status.event.dying) {
                        return get.attitude(player, _status.event.dying);
                    }
                    return 1;
                },
            },
        },
        group: "hx_tongchou_assign",
        subSkill: {
            assign: {
                trigger: {
                    player: ["useCard", "respond"],
                },
                filter(event, player) {
                    const storage = player.getStorage("hx_tongchou_used");
                    return event.skill == "hx_tongchou_backup" && _status.discarded.concat(event.cards.filterInD("od")).some(card => !storage.includes(get.type2(card)));
                },
                async cost(event, trigger, player) {
                    const cards = _status.discarded.concat(trigger.cards.filterInD("od"));
                    const types = cards.map(i => get.type2(i)).unique().removeArray(player.getStorage("hx_tongchou_used"));
                    if (types.length) {
                        const result = await player
                            .chooseButton([`###${get.prompt(event.skill)}###分配一种类别的牌`, [types.map(i => `caoying_${i}`), "vcard"]])
                            .forResult();
                        if (result.bool) {
                            const type = result.links[0][2].slice(8);
                            event.result = {
                                bool: true,
                                cost_data: [type, cards.filter(card => get.type2(card) == type)],
                            }
                        }
                    }
                },
                async content(event, trigger, player) {
                    const { cost_data: [type, cards] } = event;
                    player.addTempSkill(`hx_tongchou_used`);
                    player.markAuto("hx_tongchou_used", type);
                    const assigned = [];
                    const give_map = new Map();
                    if (_status.connectMode) {
                        game.broadcastAll(function () {
                            _status.noclearcountdown = true;
                        });
                    }
                    while (assigned.length < cards.length) {
                        const result = await player
                            .chooseButtonTarget({
                                createDialog: [`请分配这些牌`, cards.filter(i => !assigned.includes(i))],
                                forced: true,
                                filterButton: true,
                                filterTarget: true,
                                selectButton: [1, Infinity],
                                ai1(button) {
                                    if (!ui.selected.buttons.length) {
                                        return 1;
                                    }
                                    return 0;
                                },
                                ai2(target) {
                                    const player = get.player(),
                                        card = ui.selected.buttons[0].link;
                                    const val = target.getUseValue(card);
                                    if (val > 0) {
                                        return val * get.attitude(player, target) * 2;
                                    }
                                    return get.value(card, target) * get.attitude(player, target);
                                },
                            })
                            .forResult();
                        if (result?.bool && result.links?.length && result.targets?.length) {
                            const {
                                links,
                                targets: [target],
                            } = result;
                            assigned.addArray(links);
                            give_map.set(target, (give_map.get(target) || []).concat(links));
                        } else {
                            break;
                        }
                    }
                    if (_status.connectMode) {
                        game.broadcastAll(function () {
                            delete _status.noclearcountdown;
                            game.stopCountChoose();
                        });
                    }
                    player.line(Array.from(give_map.keys()), "green");
                    for (const target of Array.from(give_map.keys()).sortBySeat()) {
                        game.log(target, "获得了", give_map.get(target));
                    }
                    await game
                        .loseAsync({
                            gain_list: Array.from(give_map.entries()),
                            giver: player,
                            cards: Array.from(give_map.values()).flat(),
                            animate: "gain2",
                        })
                        .setContent("gaincardMultiple");
                },
            },
            used: {
                charlotte: true,
                onremove: true,
                intro: {
                    content: "已分配 $"
                }
            }
        }
    },


