    hx_juntian: {
	audio: "ext:华夏风云/audio/skill:2",
	limited: true,
	skillAnimation: true,
	animationColor: "metal",
	enable: "phaseUse",
	filter(event, player) {
		return !player.storage.hx_juntian;
	},
	filterTarget(card, player, target) {
		return target.isMaxHandcard(true);
	},
	async content(event, trigger, player) {
		const target = event.targets && event.targets[0];

		if (!target) {
			return;
		}

		player.storage.hx_juntian = true;
		player.awakenSkill("hx_juntian");

		const targets = game.filterPlayer((current) => {
			return current !== target;
		});

		for (const current of targets) {
			if (!target.isIn() || !current.isIn()) {
				continue;
			}

			if (!target.countCards("h")) {
				break;
			}

			await target.chooseToGive(current, "h", true);
		}

		if (target.countCards("h")) {
			target.addSkill("hx_juntian_discard");
		}
	},
	subSkill: {
		discard: {
			charlotte: true,
			forced: true,
			mark: true,
			marktext: "田",
			intro: {
				content: "每回合结束时弃置所有手牌",
			},
			trigger: {
				global: "phaseEnd",
			},
			filter(event, player) {
				return player.countDiscardableCards(player, "h") > 0;
			},
			async content(event, trigger, player) {
				await player.modedDiscard(player.getCards("h"));
			},
		},
	},
	ai: {
	order: 8,
	result: {
		target(player, target) {
			if (get.attitude(player, target) >= 0) {
				return 0;
			}
			if (!target.isMaxHandcard(true)) {
				return 0;
			}
			return -Math.max(1, game.countPlayer() - target.countCards("h"));
		},
	},
},
},


