    hx_zonghuan: {
    enable: "phaseUse",
    usable: 1,
    filter(event, player) {
        return game.hasPlayer(target => target != player && target.countCards("h") > 0);
    },
    filterTarget(card, player, target) {
        return target != player && target.countCards("h") > 0;
    },
    async content(event, trigger, player) {
    const target = event.targets[0];
    const result = await target
        .chooseToDiscard("h", true, "纵欢：请弃置任意张牌")
        .set("selectCard", [1, target.countCards("h")])
        .set("source", player)
        .set("ai", function(card) {
            const source = get.event().source;
            if (source && source.hasUseTarget(card)) {
                return 20 - get.value(card);
            }
            return 5 - get.value(card);
        })
        .forResult();
    if (result.bool && result.cards?.length) {
        const cards = result.cards.slice();
        await target.draw(cards.length);
        let unusable = 0;
        for (const card of cards) {
            if (get.position(card, true) === "d" && player.hasUseTarget(card)) {
                await player.gain([card], "gain2");
                await player
                    .chooseUseTarget(card, true)
                    .set("addCount", false);
                // 改用位置判断：牌不在手牌区说明使用成功了
                if (get.position(card) === "h") {
                    await player.discard([card]);
                    unusable++;
                }
            } else {
                unusable++;
            }
        }
        if (unusable > 0) {
            await player.draw(unusable);
        }
    }
},
    ai: {
        order: 7,
        result: {
            target(player, target) {
                const att = get.attitude(player, target);
                if (att > 0) {
                    return 2 + target.countCards("h") * 0.3;
                }
                if (att < 0) {
                    return -1;
                }
                return 0;
            },
        },
    },
},

