        // X 为你手牌中与此牌同名的牌数
        const count = player.countCards("h", card => {
            return get.name(card, player) == name;
        });

        if (count > 0) {
            if (typeof trigger.effectCount != "number") {
                trigger.effectCount = 1;
            }

            // 此牌额外结算 X 次
            trigger.effectCount += count;
        }
