hx_zhengchi: {
    audio: "ext:华夏风云/audio/skill:1",
    trigger: {
        player: "useCardAfter",
    },
    filter(event, player) {
        return event.card && event.card.name;
    },
    check(event, player) {
        var cardName = event.card.name;
        var nameLen = get.translation(cardName).replace(/【|】/g, "").length;
        var handNum = player.countCards("h");
        var diff = nameLen - handNum;
        // 摸牌必发动；弃牌超过2张不发动
        if (diff > 0) return true;
        if (diff >= -2) return true;
        return false;
    },
    async content(event, trigger, player) {
        var cardName = trigger.card.name;
        var nameLen = get.translation(cardName).replace(/【|】/g, "").length;
        var handNum = player.countCards("h");

        if (handNum === nameLen) return;

        if (handNum > nameLen) {
            var discardNum = handNum - nameLen;
            var discardRes = await player.chooseToDiscard(discardNum, true);
            if (discardRes && discardRes.bool === false) return;
            game.log(player, "将手牌数调整为", "#y" + nameLen, "张");
        } else {
            var drawNum = nameLen - handNum;
            await player.draw(drawNum);
            game.log(player, "将手牌数调整为", "#y" + nameLen, "张");
        }
    },
    ai: {
        order: 8,
        result: { player: 1 },
    },
},

