     hx_xianyi: {
    audio: "ext:华夏风云/audio/skill:3",
    trigger: {
        player: "phaseUseBegin",
    },
    filter: function (event, player) {
        return true;
    },
    check: function (event, player) {
        // AI：获得4张牌收益很高，基本都会发动
        return true;
    },
    content: function () {
        "step 0"
        // 随机获得四张花色不同的牌
        var suits = ["spade", "heart", "diamond", "club"];
        var cardNames = ["sha", "shan", "tao", "jiu", "wuxie", "guohe",
            "shunshou", "jiedao", "taoyuan", "wugu", "huogong", "tiesuo"];
        var cards = [];
        for (var i = 0; i < 4; i++) {
            var name = cardNames[Math.floor(Math.random() * cardNames.length)];
            var number = Math.ceil(Math.random() * 13);
            cards.push(game.createCard(name, suits[i], number));
        }
        player.gain(cards, "gain2");
        game.log(player, "获得了四张花色不同的牌");

        "step 1"
        var handCount = player.countCards("h");
        var minReveal = Math.ceil(handCount / 2);

        // 统一使用chooseCard，不区分AI和真人
        // selectCard设为[minReveal, minReveal]：恰好选半数张
        // 这样AI不会多选，真人也不会少选
        player.chooseCard("h", "请选择要展示的手牌（" + minReveal + "张）")
            .set("selectCard", [minReveal, minReveal])
            .set("forced", true)
            .set("prompt2", "展示的手牌本回合不可使用，且不计入手牌上限")
            .set("ai", function (card) {
                // 返回值越高越倾向于展示
                var name = get.name(card);
                var type = get.type(card);
                if (name == "shan") return 10;
                if (name == "wuxie") return 9;
                if (name == "taoyuan" || name == "wugu") return 8;
                if (type == "equip") return 6;
                if (name == "jiu") return 5;
                if (type == "trick") return 2;
                if (name == "sha") return 1;
                if (name == "tao") return 0;
                return 4;
            });

        "step 2"
        if (result.bool && result.cards && result.cards.length > 0) {
            player.storage.hx_xianyi_show = result.cards.slice();
            player.addGaintag(result.cards, "hx_xianyi_show");
            player.showCards(result.cards, get.translation(player) + "发动了【贤祎】展示的手牌");
            player.addTempSkill("hx_xianyi_restrict", { player: "phaseAfter" });
        }
        event.finish();
    },
    ai: {
        threaten: 1.5,
    },
},

