              //宋玉

    hx_cibian: {
	audio: "ext:华夏风云/audio/skill:2",
	trigger: {
		player: "damageBegin3",
	},
	filter: function (event, player) {
		// 至少保留 1 点体力上限，不能把体力上限扣到 0
		return event.num > 0 && player.maxHp > event.num;
	},
	check: function (event, player) {
		var num = event.num;

		// 不能把体力上限扣到 0
		if (player.maxHp <= num) return false;

		// 绝情伤害无法有效防止时，不发动
		if (event.source && event.source.hasSkillTag && event.source.hasSkillTag("jueqing", false, player)) {
			return false;
		}

		// 伤害会致死或很危险时，优先发动
		if (player.hp <= num) return true;

		// 受到 2 点及以上伤害，通常值得用上限换掉
		if (num >= 2) {
			// 上限较富余时更愿意发动
			if (player.maxHp - num >= Math.max(2, player.hp)) return true;
			return player.hp <= 2;
		}

		// 受到 1 点伤害时，只有体力危险或上限明显富余才发动
		if (num == 1) {
			if (player.hp <= 1) return true;
			if (player.maxHp >= player.hp + 3) return true;
			return false;
		}

		return false;
	},
	content: function () {
		"step 0"
		trigger.cancel();
		player.loseMaxHp(trigger.num);

		"step 1"
		player.draw(trigger.num);
	},
	ai: {
		filterDamage: true,
		skillTagFilter: function (player, tag, arg) {
			if (arg && arg.player) {
				if (arg.player.hasSkillTag("jueqing", false, player)) return false;
			}
			if (arg && arg.num && player.maxHp <= arg.num) return false;
		},
		effect: {
			target: function (card, player, target) {
				if (player.hasSkillTag && player.hasSkillTag("jueqing", false, target)) return;
				if (!get.tag(card, "damage")) return;
				if (target.maxHp <= 1) return;

				var num = get.tag(card, "damage");
				if (typeof num != "number") num = 1;

				// 不能把体力上限扣到 0
				if (target.maxHp <= num) return;

				// 致死伤害，强烈倾向防止
				if (target.hp <= num) return [0, 3];

				// 大伤害更适合发动
				if (num >= 2) {
					if (target.maxHp - num >= Math.max(2, target.hp)) return [0, 2];
					if (target.hp <= 2) return [0, 1.5];
					return [0, 0.8];
				}

				// 1 点伤害：只有残血或上限富余时才倾向发动
				if (target.hp <= 1) return [0, 2];
				if (target.maxHp >= target.hp + 3) return [0, 1.2];

				return;
			},
		},
	},
},

    hx_beiqiu: {
	enable: "phaseUse",
	audio: "ext:华夏风云/audio/skill:2",
	filterTarget: function (card, player, target) {
		return target.hp < target.maxHp;
	},
	content: function () {
		"step 0"
		target.loseMaxHp(true);

		"step 1"
		if (target.hp < target.maxHp) {
			target.recover();
		}
		if (target != player) {
			player.gainMaxHp(1);
		}
	},
	ai: {
		threaten: 1.8,
		expose: 0.2,
		order: function (item, player) {
			// 只要场上还有可发动的敌人，就提高优先级，促使 AI 连续发动
			var targets = game.filterPlayer(function (current) {
				return current != player &&
					current.hp < current.maxHp &&
					get.attitude(player, current) < 0;
			});

			if (targets.length) return 12;
			return 6;
		},
		result: {
			target: function (player, target) {
				var att = get.attitude(player, target);

				// 对敌人：这是削弱目标体力上限，所以返回负值
				if (att < 0) {
					if (target.maxHp <= 1) return 0;

					// 敌人体力上限越高，越值得削
					if (target.maxHp >= 5) return -4;
					if (target.maxHp >= 4) return -3;
					if (target.maxHp >= 3) return -2.5;

					// 即使上限不高，只要能削上限也有价值
					return -1.5;
				}

				// 对队友：只有残血或重伤时才认为有收益
				if (att > 0) {
					if (target.hp <= 1 && target.maxHp >= 3) return 2;
					if (target.hp == 2 && target.maxHp >= 4) return 1;
					if (target.hp < target.maxHp - 2) return 0.8;
					return -1;
				}

				// 对自己：除非很残，否则不建议
				if (target == player) {
					if (target.hp <= 1 && target.maxHp >= 3) return 1.5;
					if (target.hp < target.maxHp - 2) return 0.5;
					return -1;
				}

				return 0;
			},
			player: function (player, target) {
				var att = get.attitude(player, target);

				// 对别人发动时，自己加 1 点体力上限，这是很大的收益
				if (target != player) {
					if (att < 0) return 3;
					if (att > 0 && target.hp <= 1) return 1;
				}

				return 0;
			},
		},
	},
},

    skm: {
        audio: "xingtu",
        trigger: {
            player: "useCardAfter",
        },
        filter: function (event, player) {
            // 必须有使用的牌，且不能是虚拟牌或无点数的牌
            if (!event.cards || !event.cards.length) return false;
            // 计算有效点数总和（仅包含有明确点数的牌）
            var sum = 0;
            for (var i = 0; i < event.cards.length; i++) {
                var card = event.cards[i];
                if (typeof card.number === "number") {
                    sum += card.number;
                }
            }
            return sum > 0; // 至少有一张有效点数牌
        },
        content: function () {
            "step 0"
            // 计算打出牌的点数总和
            var sum = 0;
            for (var i = 0; i < trigger.cards.length; i++) {
                var card = trigger.cards[i];
                if (typeof card.number === "number") {
                    sum += card.number;
                }
            }
            event.sum = sum;
            "step 1"
            if (event.sum % 2 === 0) {
                // 点数和为偶数：对一名其他角色造成1点伤害
                player.chooseTarget(
                    "选择一名角色，对其造成1点伤害",
                    function (card, player, target) {
                        return target !== player;
                    }
                ).set("ai", function (target) {
                    return -get.attitude(player, target); // 优先选敌对目标
                });
            } else {
                // 点数和为奇数：获得一名其他角色的一张手牌或装备牌
                player.chooseTarget(
                    "选择一名角色，获得其一张牌",
                    function (card, player, target) {
                        return target !== player && target.countCards("he") > 0;
                    }
                ).set("ai", function (target) {
                    return -get.attitude(player, target); // 优先选敌对目标
                });
            }
            "step 2"
            if (result.bool) {
                var target = result.targets[0];
                if (event.sum % 2 === 0) {
                    target.damage(); // 造成1点伤害
                } else {
                    player.gainPlayerCard(target, "he", true); // 获得目标的一张牌（手牌或装备）
                }
            }
        },
        "_priority": 0,
    },


