    hx_huntian: {
        audio: "ext:华夏风云/audio/skill:2",
        forced: true,
        trigger: {
            global: "phaseEnd",
        },
        filter(event, player) {
            return game.countPlayer2(c => c.hasHistory("damage", evt => {
                return evt.hasNature();
            })) > 0;
        },
        content() {
            "step 0"
            var card = get.cards()[0];
            game.cardsGotoOrdering(card);
            event.cards = [card];
            event.num = get.number(card, false);
            player.showCards(card, get.translation(player) + "发动了【浑天】");
            "step 1"
            var str = get.strNumber(num);
            player.chooseControl("大于" + str, "小于" + str).set("prompt", "浑天：猜测下一张牌的点数").set("choice", num < 7 ? 0 : 1).set("ai", () => _status.event.choice);
            "step 2"
            var card = get.cards()[0];
            game.cardsGotoOrdering(card);
            event.cards.push(card);
            var num = get.number(card, false);
            player.showCards(card);
            if (num > event.num && result.index == 0 || num < event.num && result.index == 1) {
                player.gain(cards, "gain2");
                player.recover();
                event.finish();
            } else {
                game.cardsGotoOrdering(event.cards);
                var next = player.chooseToMove();
                next.set("list", [
                    ["牌堆顶", cards],
                    ["牌堆底"],
                ]);
                next.set("prompt", "浑天：点击将牌移动到牌堆顶或牌堆底");
                next.processAI = function (list) {
                    var cards = list[0][1], player = _status.event.player;
                    var target = (_status.event.getTrigger().name == "phaseZhunbei") ? player : player.next;
                    var att = get.sgn(get.attitude(player, target));
                    var top = [];
                    var judges = target.getCards("j");
                    var stopped = false;
                    if (player != target || !target.hasWuxie()) {
                        for (var i = 0; i < judges.length; i++) {
                            var judge = get.judge(judges[i]);
                            cards.sort(function (a, b) {
                                return (judge(b) - judge(a)) * att;
                            });
                            if (judge(cards[0]) * att < 0) {
                                stopped = true;
                                break;
                            } else {
                                top.unshift(cards.shift());
                            }
                        }
                    }
                    var bottom;
                    if (!stopped) {
                        cards.sort(function (a, b) {
                            return (get.value(b, player) - get.value(a, player)) * att;
                        });
                        while (cards.length) {
                            if ((get.value(cards[0], player) <= 5) == (att > 0)) break;
                            top.unshift(cards.shift());
                        }
                    }
                    bottom = cards;
                    return [top, bottom];
                }
            }
            "step 3"
            var top = result.moved[0];
            var bottom = result.moved[1];
            top.reverse();
            for (var i = 0; i < top.length; i++) {
                ui.cardPile.insertBefore(top[i], ui.cardPile.firstChild);
            }
            for (i = 0; i < bottom.length; i++) {
                ui.cardPile.appendChild(bottom[i]);
            }
            player.popup(get.cnNumber(top.length) + "上" + get.cnNumber(bottom.length) + "下");
            game.log(player, "将" + get.cnNumber(top.length) + "张牌置于牌堆顶");
            game.updateRoundNumber();
            game.delayx();
        },
        ai: {
            threaten: 2.2,
        },
    },
