        //魔赵高

    mo_zhiluweima: {
    audio: "ext:华夏风云/audio/skill:2",
    trigger: {
        player: "useCard",
        target: "useCardToTargeted",
    },
    direct: true,
    filter(event, player) {
        // 正在使用牌或成为牌目标时可发动
        return true;
    },
    async content(event, trigger, player) {
        // 选目标：AI 优先选受伤敌方或关键角色
        const aiTarget = game.filterPlayer(current => {
            return !current.isUnseen() && !current.isMin();
        }).sort((a, b) => {
            const evalTarget = (current) => {
                const att = get.attitude(player, current);
                if (att < 0 && current.isDamaged() && current.hp <= 3) return -10;
                const rank = get.rank(current, true) || 5;
                if (current.maxHp >= 3) {
                    if (current.hp <= 1) {
                        return att > 0 ? att * 3 + 2 : att * 3;
                    } else if (current.hp == 2) {
                        return att > 0 ? att * 1.5 : att / 1.5;
                    }
                }
                if (rank >= 7) {
                    return att > 0 ? att / 10 : -att / 5;
                } else if (rank <= 4) {
                    return att < 0 ? -att / 10 : att;
                }
                return Math.abs(att / 2);
            };
            return evalTarget(b) - evalTarget(a);
        })[0];

        // 获取可选武将牌
        const list = [];
        for (const i in lib.character) {
            if (!lib.filter.characterDisabled(i) && !lib.filter.characterDisabled2(i)) {
                list.push(i);
            }
        }
        const players = game.players.concat(game.dead);
        for (let i = 0; i < players.length; i++) {
            list.remove(players[i].name);
            list.remove(players[i].name1);
            list.remove(players[i].name2);
        }

        const num = 5 + player.countMark("mo_zhiluweima");
        const choices = list.randomGets(num);
        if (!choices.length) return;

        // 选武将牌
        const dialog = ui.create.dialog("指鹿为马：选择一张武将牌", "hidden");
        dialog.add([choices, "character"]);

        const result1 = await player.chooseButton(dialog, false)
            .set("ai", button => {
                const player = get.player();
                const target = _status.event.aitarget;
                if (!target) return get.rank(button.link, true) || 5;

                const att = get.attitude(player, target);
                const rank = get.rank(button.link, true) || 5;

                // 对友方：选强将
                if (att > 0) return rank;
                // 对敌方：选弱将
                return -rank;
            })
            .set("aitarget", aiTarget)
            .forResult();

        if (!result1.bool || !result1.links?.length) return;

        const newName = result1.links[0];

        // 选要替换的角色
        const result2 = await player.chooseTarget(
            false,
            "指鹿为马：使用" + get.translation(newName) + "替换一名角色的武将牌",
            (card, player, target) => {
                return !target.isUnseen() && !target.isMin();
            }
        )
            .set("ai", target => {
                const aitarget = _status.event.aitarget;
                if (target == aitarget) return 1;
                return 0;
            })
            .set("aitarget", aiTarget)
            .forResult();

        if (!result2.bool || !result2.targets?.length) return;

        const target = result2.targets[0];
        const oldName = target.name1 || target.name;

        // 记录原武将名，用于还原
        if (!target.storage.mo_zhiluweima) {
            target.storage.mo_zhiluweima = [oldName, target.name2];
        }

        player.logSkill("mo_zhiluweima", target);
        player.line(target, "green");

        // 换将
        target.reinit(oldName, newName);
        target.update();

        // 添加临时还原技能，在牌结算后还原
        target.addTempSkill("mo_zhiluweima_restore");
        target.storage.mo_zhiluweima_restore_trigger = trigger;
    },
    ai: {
        threaten: 2,
        expose: 0.3,
    },
    subSkill: {
        restore: {
            charlotte: true,
            trigger: {
                global: "useCardAfter",
            },
            forced: true,
            popup: false,
            filter(event, player) {
                return player.storage.mo_zhiluweima &&
                    event == player.storage.mo_zhiluweima_restore_trigger;
            },
            content() {
                const storage = player.storage.mo_zhiluweima;
                if (storage && storage.length >= 1) {
                    const oldName = storage[0];
                    const currentName = player.name1 || player.name;
                    player.reinit(currentName, oldName);
                    player.update();
                }
                delete player.storage.mo_zhiluweima;
                delete player.storage.mo_zhiluweima_restore_trigger;
                player.removeSkill("mo_zhiluweima_restore");
            },
        },
    },
},


