    //钟馗

    shen_panguan: {
    audio: "ext:华夏风云/audio/skill:3",
    trigger: {
        global: "judgeBefore",
    },
    charlotte: true,
    lastDo: true,
    logTarget: "player",
    priority: 2,
    direct: true,
    filter(event, player) {
        return !player.storage.shen_panguan_used;
    },
    getVCardList() {
        const list = [];
        for (const name of lib.inpile) {
            if (name === "sha") {
                list.push(["basic", "", "sha"]);
                list.push(["basic", "", "sha", "fire"]);
                list.push(["basic", "", "sha", "thunder"]);
                list.push(["basic", "", "sha", "ice"]);
                list.push(["basic", "", "sha", "kami"]);
            } else {
                const type = get.type(name);
                if (type === "trick") {
                    list.push(["trick", "", name]);
                } else if (type === "delay") {
                    list.push(["delay", "", name]);
                } else if (type === "basic") {
                    list.push(["basic", "", name]);
                } else if (type === "equip") {
                    list.push(["equip", "", name]);
                }
            }
        }
        return list;
    },
    getJudgeValue(trigger, info) {
        const card = {
            name: info.name,
            suit: info.suit,
            number: info.number,
            nature: info.nature,
        };
        return trigger.judge(card);
    },
    getBestResult(trigger, player, list) {
        const suits = ["spade", "heart", "club", "diamond"];
        const attitude = get.attitude(player, trigger.player);
        let best = null;
        let bestValue = -Infinity;
        for (const vcard of list) {
            for (const suit of suits) {
                for (let number = 1; number <= 13; number++) {
                    const info = {
                        vcard,
                        name: vcard[2],
                        nature: vcard[3],
                        suit,
                        number,
                    };
                    const judge = lib.skill.shen_panguan.getJudgeValue(trigger, info);
                    const value = judge * attitude;
                    if (value > bestValue) {
                        bestValue = value;
                        best = info;
                    }
                }
            }
        }
        return best;
    },
    async content(event, trigger, player) {
        const list = lib.skill.shen_panguan.getVCardList();
        if (!list.length) return;

        const best = lib.skill.shen_panguan.getBestResult(trigger, player, list);

        const boolResult = await player
            .chooseBool(get.prompt("shen_panguan", trigger.player), `是否修改${get.translation(trigger.player)}的判定结果？`)
            .set("ai", () => true)
            .forResult();
        if (!boolResult?.bool) return;

        const cardDialog = ui.create.dialog("判官：请选择判定牌名", [list, "vcard"]);
        const cardResult = await player
            .chooseButton(cardDialog, true)
            .set("ai", (button) => {
                const best = _status.event.best;
                if (best && button.link === best.vcard) return 1000;
                return Math.random();
            })
            .set("best", best)
            .forResult();
        if (!cardResult?.bool || !cardResult.links?.length) return;

        const vcard = cardResult.links[0];
        const suitResult = await player
            .chooseControl("spade", "heart", "club", "diamond")
            .set("prompt", "判官：请选择判定花色")
            .set("ai", () => {
                const best = _status.event.best;
                return best?.suit || "spade";
            })
            .set("best", best)
            .forResult();
        if (!suitResult?.control) return;

        const numberList = [];
        for (let i = 1; i <= 13; i++) numberList.push(String(i));
        const numberResult = await player
            .chooseControl(...numberList)
            .set("prompt", "判官：请选择判定点数")
            .set("ai", () => {
                const best = _status.event.best;
                return String(best?.number || 1);
            })
            .set("best", best)
            .forResult();
        if (!numberResult?.control) return;

        // 只有真正完成修改才标记为已使用
        player.storage.shen_panguan_used = true;
        player.addTempSkill("shen_panguan_used", { player: "phaseBegin" });

        const name = vcard[2];
        const nature = vcard[3];
        const suit = suitResult.control;
        const number = Number(numberResult.control);

        const fixedResult = {
            name,
            suit,
            color: get.color({ suit }),
            number,
            nature,
        };

        const card = game.createCard(fixedResult);
        const judge = trigger.judge(card);

        Object.assign(fixedResult, { card, judge });

        player.logSkill("shen_panguan", trigger.player);

        trigger.fixedResult = fixedResult;
        if (!trigger.result) trigger.result = {};
        Object.assign(trigger.result, fixedResult);
        trigger.result.bool = judge > 0;

        if (trigger.player.judging && trigger.player.judging.length) {
            Object.assign(trigger.player.judging[0], fixedResult);
        }

        trigger.noJudgeTrigger = true;
        trigger.direct = true;
        trigger.cancel();

        game.log(player, "将", trigger.player, "的判定结果修改为了", card);

        if (judge > 0) {
            trigger.player.popup("洗具");
        } else if (judge < 0) {
            trigger.player.popup("杯具");
        }

        game.log(trigger.player, "的判定结果为", card);

        if (trigger.position) {
            trigger.position.appendChild(card);
        }

        game.delayx();
    },
    subSkill: {
        used: {
            charlotte: true,
            silent: true,
            onremove(player) {
                delete player.storage.shen_panguan_used;
            },
        },
    },
},


