    hx_shanzheng: {
    audio: "ext:华夏风云/audio/skill:2", 
    enable: "phaseUse",
    zhuanhuanji: true,  
    marktext: "☯",
    init(player) {
        player.addSkill("hx_shanzheng_effect");
    },
    filter(event, player) {
        var cards = player.getCards('h', function(card) {
            return card.hasGaintag('hx_shanzheng_tag');
        });
        return cards.length === 0;
    },
    intro: {
        content(storage, player) {
            if (storage === true) {
                return "出牌阶段，若你的手牌中没有【善正】标记的牌，可从【牌堆底】摸一张牌并对其进行标记（此牌使用无距离和次数限制）。然后切换转换技状态。";
            }
            return "出牌阶段，若你的手牌中没有【善正】标记的牌，可从【牌堆顶】摸一张牌并对其进行标记（此牌使用无距离和次数限制）。然后切换转换技状态。";
        },
    },
    async content(event, trigger, player) {
        let card;
        // 注意：无名杀标准转换技存储状态的 key 通常是 技能名_zhuanhuanji
        let isBottom = player.getStorage(event.name + '_zhuanhuanji') === true; 
        
        if (isBottom) {
            card = get.bottomCards()[0]; 
            if (card) { game.log(player, '从', '#y牌堆底', '摸了一张牌'); }
        } else {
            card = get.cards()[0];       
            if (card) { game.log(player, '从', '#y牌堆顶', '摸了一张牌'); }
        }
        
        if (card) {
            await player.gain(card, 'draw');
            player.addGaintag(card, 'hx_shanzheng_tag'); 
        }

        player.changeZhuanhuanji(event.name);
    },
    
    // ========== 🧠 这里是为 AI 注入灵魂的控制台 ==========
    ai: {
        order: 9, // 发动优先级调高（接近摸牌阶段的收益），让 AI 在出牌阶段刚开始时优先摸这张牌
        result: {
            player: 1 // 告诉 AI，发动这个技能对自己有正收益（价值 1 纯收益）
        },
        // 核心：让 AI 聪明地使用带有【善正】标记的牌
        tag: {
            // 无名杀内置的常用 AI 行为劫持
            cardRespond(card, player) {
                // 如果 AI 此时需要响应某张牌（比如被【借刀杀人】或者响应【南蛮】），优先交出这张牌
                if (card.hasGaintag('hx_shanzheng_tag')) return 2;
                return 1;
            }
        }
    },
    
    subSkill: {
        effect: {
            charlotte: true,
            // 在子技能里强化 AI 选牌逻辑
            ai: {
                // 这个标记能让 AI 在准备使用某类牌（比如【杀】）时，优先在手牌里挑选带有【善正】标记的牌
                useful_gaintag: ['hx_shanzheng_tag']
            },
            mod: {
                targeter(card, player, target) {
                    if (card && card.cards) {
                        for (var i of card.cards) {
                            if (i.hasGaintag('hx_shanzheng_tag')) return true;
                        }
                    }
                    if (card && card.hasGaintag('hx_shanzheng_tag')) return true;
                },
                cardUsable(card, player, num) {
                    if (card && card.cards) {
                        for (var i of card.cards) {
                            if (i.hasGaintag('hx_shanzheng_tag')) return Infinity;
                        }
                    }
                    if (card && card.hasGaintag('hx_shanzheng_tag')) return Infinity;
                }
            },
            sub: true,
            sourceSkill: "hx_shanzheng"
        }
    }
},
    
    
